import { toBlobURL } from '@ffmpeg/util';

const MSG = {
  LOAD: 'LOAD', EXEC: 'EXEC', WRITE_FILE: 'WRITE_FILE',
  READ_FILE: 'READ_FILE', DELETE_FILE: 'DELETE_FILE',
  ERROR: 'ERROR', LOG: 'LOG', PROGRESS: 'PROGRESS',
} as const;

class FFmpegService {
  private worker: Worker | null = null;
  private loaded = false;
  private msgId = 0;
  private callbacks = new Map<number, {
    resolve: (v: any) => void;
    reject: (e: any) => void;
  }>();
  private logCb: ((msg: string) => void) | null = null;
  private progressCb: ((p: { progress: number }) => void) | null = null;

  async load(onLog?: (msg: string) => void) {
    if (this.loaded && this.worker) return;
    this.logCb = onLog || null;

    const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';
    const coreURL = await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript');
    const wasmURL = await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm');

    const workerBlob = this.buildWorkerBlob();
    this.worker = new Worker(workerBlob);

    this.worker.onmessage = ({ data: { id, type, data } }) => {
      if (type === MSG.LOG) {
        this.logCb?.(data?.message || '');
        return;
      }
      if (type === MSG.PROGRESS) {
        this.progressCb?.(data);
        return;
      }
      if (type === MSG.ERROR) {
        const cb = this.callbacks.get(id);
        if (cb) { this.callbacks.delete(id); cb.reject(new Error(data)); }
        return;
      }
      const cb = this.callbacks.get(id);
      if (cb) { this.callbacks.delete(id); cb.resolve(data); }
    };

    await this.send(MSG.LOAD, { coreURL, wasmURL });
    this.loaded = true;
  }

  private send(type: string, data?: any): Promise<any> {
    return new Promise((resolve, reject) => {
      const id = this.msgId++;
      this.callbacks.set(id, { resolve, reject });
      this.worker!.postMessage({ id, type, data });
    });
  }

  private buildWorkerBlob(): string {
    const script = `
var MSG = { LOAD: "LOAD", EXEC: "EXEC", WRITE_FILE: "WRITE_FILE", READ_FILE: "READ_FILE", DELETE_FILE: "DELETE_FILE", ERROR: "ERROR", LOG: "LOG", PROGRESS: "PROGRESS" };
var ffmpeg = null;
var load = function(opts) {
  importScripts(opts.coreURL);
  return self.createFFmpegCore({
    mainScriptUrlOrBlob: opts.coreURL + "#" + btoa(JSON.stringify({ wasmURL: opts.wasmURL })),
  }).then(function(core) {
    ffmpeg = core;
    ffmpeg.setLogger(function(data) { self.postMessage({ type: MSG.LOG, data: data }); });
    ffmpeg.setProgress(function(data) { self.postMessage({ type: MSG.PROGRESS, data: data }); });
    return true;
  });
};
self.onmessage = function(e) {
  var id = e.data.id, type = e.data.type, _data = e.data.data, trans = [], data;
  var handleResult = function(result) {
    data = result;
    if (data instanceof Uint8Array) trans.push(data.buffer);
    self.postMessage({ id: id, type: type, data: data }, trans);
  };
  var handleError = function(err) { self.postMessage({ id: id, type: MSG.ERROR, data: err.toString() }); };
  try {
    if (type !== MSG.LOAD && !ffmpeg) return handleError("ffmpeg not loaded");
    switch (type) {
      case MSG.LOAD: load(_data).then(handleResult).catch(handleError); return;
      case MSG.EXEC: ffmpeg.exec.apply(ffmpeg, _data.args); data = ffmpeg.ret; ffmpeg.reset(); break;
      case MSG.WRITE_FILE: ffmpeg.FS.writeFile(_data.path, _data.data); data = true; break;
      case MSG.READ_FILE: data = ffmpeg.FS.readFile(_data.path); break;
      case MSG.DELETE_FILE: ffmpeg.FS.unlink(_data.path); data = true; break;
      default: return handleError("unknown type: " + type);
    }
  } catch (err) { return handleError(err); }
  if (data instanceof Uint8Array) trans.push(data.buffer);
  self.postMessage({ id: id, type: type, data: data }, trans);
};`;
    return URL.createObjectURL(new Blob([script], { type: 'text/javascript' }));
  }

  async exec(args: string[]) { return this.send(MSG.EXEC, { args }); }
  async writeFile(name: string, data: Uint8Array) { return this.send(MSG.WRITE_FILE, { path: name, data }); }
  async readFile(name: string) { return this.send(MSG.READ_FILE, { path: name }); }
  async deleteFile(name: string) { return this.send(MSG.DELETE_FILE, { path: name }); }
  onProgress(cb: (p: { progress: number }) => void) { this.progressCb = cb; }
}

export const ffmpegService = new FFmpegService();

export type LayerType = 'Ambience' | 'Foley' | 'SFX';
export type SFXMode = 'Source' | 'Designed';

export type AcousticEnv = 'Studio' | 'Warehouse' | 'Chamber' | 'Field' | 'Forest' | 'Small Room' | 'Underwater';
export type MicStyle = 'Condenser' | 'Shotgun' | 'Binaural' | 'Dynamic' | 'Vintage' | 'Phone';

export type SoundCharacter = 
  | 'Studio' 
  | 'Cinematic' 
  | 'ASMR' 
  | 'Vintage' 
  | 'Industrial' 
  | 'Abstract';

export interface FocusArea {
  x: number; // 0 to 1
  y: number; // 0 to 1
  w: number; // 0 to 1
  h: number; // 0 to 1
}

export interface SoundLayer {
  id: string;
  type: 'Ambience';
  time: number;
  prompt: string;
  soundCharacter: SoundCharacter;
  environment: AcousticEnv;
  mic: MicStyle;
  volume: number;
  pan: number;
  isMuted: boolean;
  isSolo: boolean;
  audioUrl: string | null;
  audioBase64: string | null;
  waveform?: number[];
  status: 'idle' | 'generating' | 'ready' | 'error' | 'processing';
  trimStart: number;
  trimEnd: number;
  fadeInMs?: number;
  fadeOutMs?: number;
}

export interface Marker {
  id: string;
  type: 'Foley' | 'SFX';
  sfxMode?: SFXMode;
  time: number;
  trimStart: number;
  trimEnd: number;
  fadeInMs?: number;
  fadeOutMs?: number;
  prompt: string;
  soundCharacter: SoundCharacter;
  environment: AcousticEnv;
  mic: MicStyle;
  volume: number;
  pan: number;
  isMuted: boolean;
  isSolo: boolean;
  audioUrl: string | null;
  audioBase64: string | null;
  waveform?: number[];
  focusArea?: FocusArea;
  status: 'idle' | 'generating' | 'ready' | 'error' | 'processing';
}

export type AppStatus = 'ready' | 'busy' | 'error';

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Flow } from 'flow-sdk';
import { ffmpegService } from './services/ffmpegService';
import { audioEngine } from './services/audioEngine';
import { useSoundEngine } from './hooks/useSoundEngine';
import { SoundLayer, Marker } from './types';
import { SectionLabel, PillButton, RangeSlider, SegmentedToggle } from './components/Primitives';
import { SoundStem } from './components/SoundStem';
import { Timeline } from './components/Timeline';
import { MarkerItem } from './components/MarkerItem';
import { MasterMeter } from './components/MasterMeter';
import { AreaSelector } from './components/AreaSelector';
import { SessionManager } from './components/SessionManager';
import { MediaIcon, MondoLogo, StemIcon } from './components/CustomIcons';
import { SoundKey } from './components/SoundKey';
import { ControlKey } from './components/ControlKey';
import { WelcomeModal } from './components/WelcomeModal';
import { ToastContainer, ToastMessage, ToastType } from './components/Toast';

export default function App() {
  const [media, setMedia] = useState<any>(null);
  const [ambientLayers, setAmbientLayers] = useState<SoundLayer[]>([]);
  const [markers, setMarkers] = useState<Marker[]>([]);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(8);
  const [isPlaying, setIsPlaying] = useState(false);
  const [masterVolume, setMasterVolume] = useState(100);
  const [sourceVolume, setSourceVolume] = useState(30);
  const [genMode, setGenMode] = useState<'fast' | 'high'>('fast');
  const [activeTargetId, setActiveTargetId] = useState<string | null>(null);
  const [isWelcomeOpen, setIsWelcomeOpen] = useState(true);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [lastAddedId, setLastAddedId] = useState<string | null>(null);
  const [includeMaster, setIncludeMaster] = useState(false);

  const { isBusy, status, setStatus, generateAudio, renderMaster, exportStems } = useSoundEngine();
  const videoRef = useRef<HTMLVideoElement>(null);
  const sidebarRef = useRef<HTMLDivElement>(null);
  const lastMarkerTrigger = useRef<{ [key: string]: number }>({});
  const prevTimeRef = useRef(0);
  const requestRef = useRef<number>(null);

  useEffect(() => {
    ffmpegService.load().catch(() => setStatus('FFmpeg Load Error'));

    const id = 'mondo-sonico-styles';
    if (!document.getElementById(id)) {
      const style = document.createElement('style');
      style.id = id;
      style.textContent = `
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #D1CABD; border-radius: 10px; }
        @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
        body { background-color: #fbfaf7; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        @keyframes zoom-in-95 { from { transform: scale(0.95); } to { transform: scale(1); } }
        @keyframes slide-in-from-bottom-8 { from { transform: translateY(2rem); } to { transform: translateY(0); } }
        @keyframes slide-in-from-bottom-4 { from { transform: translateY(1rem); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation-fill-mode: forwards; }
        .fade-in { animation-name: fade-in; }
        .zoom-in-95 { animation-name: zoom-in-95; }
        .slide-in-from-bottom-8 { animation-name: slide-in-from-bottom-8; }
        .slide-in-from-bottom-4 { animation-name: slide-in-from-bottom-4; }
      `;
      document.head.appendChild(style);
    }
  }, [setStatus]);

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
    if (videoRef.current) videoRef.current.volume = (sourceVolume / 100);
  }, [masterVolume, sourceVolume]);

  const addToast = (message: string, type: ToastType) => {
    const id = `t-${Date.now()}`;
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const isInitialized = useMemo(() => {
    return !!media || ambientLayers.length > 0 || markers.length > 0;
  }, [media, ambientLayers, markers]);

  const hasGeneratedAudio = useMemo(() => {
    return ambientLayers.some(l => !!l.audioBase64) || markers.some(m => !!m.audioBase64);
  }, [ambientLayers, markers]);

  const validateInteraction = useCallback(() => {
    if (!isInitialized) {
      addToast("load media or a project to begin", "Error");
      return false;
    }
    return true;
  }, [isInitialized]);

  useEffect(() => {
    if (lastAddedId) {
      const el = document.getElementById(lastAddedId);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        setLastAddedId(null);
      }
    }
  }, [lastAddedId]);

  const handleSelectMedia = async () => {
    try {
      const s = await Flow.media.select({ filter: 'video' });
      if (s) {
        setMedia(s);
      }
    } catch (err) {
      console.log('Media selection cancelled or failed:', err);
    }
  };

  /** 
   * DAW Logic Update Helpers
   * 1. Solo button clicked: Toggle isSolo. If result is true, clear isMuted. (Additive)
   * 2. Mute button clicked: Toggle isMuted. If result is true, clear isSolo.
   */
  const updateAmbientLayer = useCallback((id: string, updates: Partial<SoundLayer>) => {
    setAmbientLayers(prev => prev.map(l => {
      if (l.id !== id) return l;
      let next = { ...l, ...updates };
      if (updates.isSolo === true) next.isMuted = false;
      if (updates.isMuted === true) next.isSolo = false;
      return next;
    }));
  }, []);

  const updateMarker = useCallback((id: string, updates: Partial<Marker>) => {
    setMarkers(prev => prev.map(m => {
      if (m.id !== id) return m;
      let next = { ...m, ...updates };
      if (updates.isSolo === true) next.isMuted = false;
      if (updates.isMuted === true) next.isSolo = false;
      return next;
    }));
  }, []);

  const addAmbience = () => {
    if (!validateInteraction()) return;
    const id = `l-${Date.now()}`;
    setAmbientLayers(p => [...p, { id, type: 'Ambience', time: currentTime, prompt: '', soundCharacter: 'Studio', environment: 'Studio', mic: 'Condenser', volume: 80, pan: 0, isMuted: false, isSolo: false, audioUrl: null, audioBase64: null, status: 'idle', trimStart: 0, trimEnd: 8, fadeInMs: 100, fadeOutMs: 100 }]);
    setLastAddedId(id);
  };

  const addFoley = () => {
    if (!validateInteraction()) return;
    const id = `m-${Date.now()}`;
    setMarkers(p => [...p, { id, type: 'Foley', time: currentTime, trimStart: 0, trimEnd: 8.0, fadeInMs: 100, fadeOutMs: 100, prompt: '', soundCharacter: 'Studio', environment: 'Studio', mic: 'Condenser', volume: 80, pan: 0, isMuted: false, isSolo: false, audioUrl: null, audioBase64: null, status: 'idle' }]);
    setLastAddedId(id);
  };

  const addSFX = () => {
    if (!validateInteraction()) return;
    const id = `s-${Date.now()}`;
    setMarkers(p => [...p, { id, type: 'SFX', sfxMode: 'Source', time: currentTime, trimStart: 0, trimEnd: 8.0, fadeInMs: 50, fadeOutMs: 50, prompt: '', soundCharacter: 'Studio', environment: 'Studio', mic: 'Condenser', volume: 80, pan: 0, isMuted: false, isSolo: false, audioUrl: null, audioBase64: null, status: 'idle' }]);
    setLastAddedId(id);
  };

  const handleDuplicateMarker = useCallback(async (m: Marker) => {
    const newId = `${m.id.split('-')[0]}-${Date.now()}`;
    const duplicate: Marker = { 
      ...m, 
      id: newId, 
      time: currentTime,
      isSolo: false, 
      isMuted: false,
      status: m.audioBase64 ? 'ready' : 'idle'
    };
    if (m.audioBase64) await audioEngine.loadBuffer(newId, m.audioBase64);
    setMarkers(prev => [...prev, duplicate]);
    setLastAddedId(newId);
  }, [currentTime]);

  const handleDuplicateLayer = useCallback(async (l: SoundLayer) => {
    const newId = `l-${Date.now()}`;
    const duplicate: SoundLayer = {
      ...l,
      id: newId,
      time: currentTime,
      isSolo: false,
      isMuted: false,
      status: l.audioBase64 ? 'ready' : 'idle'
    };
    if (l.audioBase64) await audioEngine.loadBuffer(newId, l.audioBase64);
    setAmbientLayers(prev => [...prev, duplicate]);
    setLastAddedId(newId);
  }, [currentTime]);

  const handleGenerateAmbience = async (layerId: string, prompt: string, env: any, mic: any, character: any) => {
    setAmbientLayers(p => p.map(o => o.id === layerId ? {...o, status: 'generating'} : o));
    try {
      const res = await generateAudio(prompt, genMode, 'Ambience', env, mic, undefined, false, undefined, character);
      await audioEngine.loadBuffer(layerId, res.base64);
      setAmbientLayers(p => p.map(o => o.id === layerId ? { ...o, audioUrl: res.url, audioBase64: res.base64, waveform: res.waveform, status: 'ready' } : o));
    } catch { 
      setAmbientLayers(p => p.map(o => o.id === layerId ? {...o, status: 'error'} : o)); 
      addToast("Synthesis Failed", "Error");
    }
  };

  const handleGenerateMarker = async (markerId: string, type: string, prompt: string, env: any, mic: any, sfxMode: any, character: any, focusArea: any) => {
    setMarkers(p => p.map(o => o.id === markerId ? {...o, status: 'generating'} : o));
    try {
      const target = markers.find(m => m.id === markerId);
      const captureFrameId = async (m?: Marker): Promise<string | undefined> => {
        if (!videoRef.current) return undefined;
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return undefined;
        let sx = 0, sy = 0, sw = videoRef.current.videoWidth, sh = videoRef.current.videoHeight;
        if (m?.focusArea) {
          sx = m.focusArea.x * sw; sy = m.focusArea.y * sh;
          sw = m.focusArea.w * sw; sh = m.focusArea.h * sh;
        }
        canvas.width = sw; canvas.height = sh;
        ctx.drawImage(videoRef.current, sx, sy, sw, sh, 0, 0, sw, sh);
        const b64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        const upload = await Flow.upload({ base64: b64, mimeType: 'image/jpeg', name: `Ref_${Date.now()}` });
        return upload.mediaId;
      };
      const frameId = (type === 'Foley' || sfxMode === 'Source') ? await captureFrameId(target) : undefined;
      const res = await generateAudio(prompt, genMode, type as any, env, mic, frameId, !!focusArea, sfxMode, character);
      await audioEngine.loadBuffer(markerId, res.base64);
      setMarkers(p => p.map(o => o.id === markerId ? { ...o, audioUrl: res.url, audioBase64: res.base64, waveform: res.waveform, status: 'ready' } : o));
    } catch { 
      setMarkers(p => p.map(o => o.id === markerId ? {...o, status: 'error'} : o)); 
      addToast("Synthesis Failed", "Error");
    }
  };

  const anySoloActive = useMemo(() => 
    ambientLayers.some(l => l.isSolo) || markers.some(m => m.isSolo),
  [ambientLayers, markers]);

  const recomputePlayback = useCallback((time: number) => {
    audioEngine.stopAll();
    lastMarkerTrigger.current = {};

    ambientLayers.forEach(l => {
      if (!l.audioBase64) return;
      const isAudible = !l.isMuted && (!anySoloActive || l.isSolo);
      if (!isAudible) return;

      const tS = l.trimStart || 0, tE = l.trimEnd || 8;
      const clipDur = tE - tS;
      if (time >= l.time && time < l.time + clipDur) {
        const offset = time - l.time;
        audioEngine.playLayer(l.id, { 
          offset, volume: l.volume, pan: l.pan, isMuted: false, 
          trimStart: tS, trimEnd: tE, timelineDuration: clipDur,
          fadeInMs: l.fadeInMs || 0, fadeOutMs: l.fadeOutMs || 0
        });
        lastMarkerTrigger.current[l.id] = time;
      }
    });

    markers.forEach(m => {
      if (!m.audioBase64) return;
      const isAudible = !m.isMuted && (!anySoloActive || m.isSolo);
      if (!isAudible) return;

      const duration = m.trimEnd - m.trimStart;
      if (time >= m.time && time < m.time + duration) {
        const offset = time - m.time;
        audioEngine.playMarker(m.id, { 
          trimStart: m.trimStart, trimEnd: m.trimEnd, 
          fadeInMs: m.fadeInMs || 0, fadeOutMs: m.fadeOutMs || 0, 
          volume: m.volume, pan: m.pan, isMuted: false, offset 
        });
        lastMarkerTrigger.current[m.id] = time;
      }
    });
  }, [ambientLayers, markers, anySoloActive]);

  useEffect(() => {
    if (!isPlaying || !videoRef.current) return;
    const time = videoRef.current.currentTime;

    ambientLayers.forEach(l => {
      const isAudible = !l.isMuted && (!anySoloActive || l.isSolo);
      const isActiveInEngine = audioEngine.isActive(l.id);
      const tS = l.trimStart || 0, tE = l.trimEnd || 8;
      const clipDur = tE - tS;

      if (isAudible && !isActiveInEngine) {
        if (time >= l.time && time < l.time + clipDur) {
          const offset = time - l.time;
          audioEngine.playLayer(l.id, { 
            offset, volume: l.volume, pan: l.pan, isMuted: false, 
            trimStart: tS, trimEnd: tE, timelineDuration: clipDur,
            fadeInMs: l.fadeInMs || 0, fadeOutMs: l.fadeOutMs || 0
          });
        }
      } else if (!isAudible && isActiveInEngine) {
        audioEngine.stop(l.id);
      }
    });

    markers.forEach(m => {
      const isAudible = !m.isMuted && (!anySoloActive || m.isSolo);
      const isActiveInEngine = audioEngine.isActive(m.id);
      const clipDur = m.trimEnd - m.trimStart;

      if (isAudible && !isActiveInEngine) {
        if (time >= m.time && time < m.time + clipDur) {
          const offset = time - m.time;
          audioEngine.playMarker(m.id, { 
            trimStart: m.trimStart, trimEnd: m.trimEnd, 
            fadeInMs: m.fadeInMs || 0, fadeOutMs: m.fadeOutMs || 0, 
            volume: m.volume, pan: m.pan, isMuted: false, offset 
          });
        }
      } else if (!isAudible && isActiveInEngine) {
        audioEngine.stop(m.id);
      }
    });
  }, [anySoloActive, ambientLayers, markers, isPlaying]);

  const sync = useCallback(() => {
    if (!videoRef.current || !isPlaying) return;
    const time = videoRef.current.currentTime;
    const delta = time - prevTimeRef.current;

    if (Math.abs(delta) > 0.3) {
      recomputePlayback(time);
    } else {
      ambientLayers.forEach(l => {
        if (!l.audioBase64) return;
        const isAudible = !l.isMuted && (!anySoloActive || l.isSolo);
        if (!isAudible) return;

        const tS = l.trimStart || 0, tE = l.trimEnd || 8;
        const clipDur = tE - tS;
        const lastT = lastMarkerTrigger.current[l.id] || -1;
        if (time >= l.time && time < l.time + clipDur && time <= (l.time + 0.1) && Math.abs(time - lastT) > 0.3) {
          audioEngine.playLayer(l.id, { 
            offset: 0, volume: l.volume, pan: l.pan, isMuted: false, 
            trimStart: tS, trimEnd: tE, timelineDuration: clipDur,
            fadeInMs: l.fadeInMs || 0, fadeOutMs: l.fadeOutMs || 0
          });
          lastMarkerTrigger.current[l.id] = time;
        }
      });

      markers.forEach(m => {
        if (!m.audioBase64) return;
        const isAudible = !m.isMuted && (!anySoloActive || m.isSolo);
        if (!isAudible) return;

        const lastT = lastMarkerTrigger.current[m.id] || -1;
        const clipDur = m.trimEnd - m.trimStart;
        if (time >= m.time && time < m.time + clipDur && time <= (m.time + 0.1) && Math.abs(time - lastT) > 0.3) {
          audioEngine.playMarker(m.id, { trimStart: m.trimStart, trimEnd: m.trimEnd, fadeInMs: m.fadeInMs || 0, fadeOutMs: m.fadeOutMs || 0, volume: m.volume, pan: m.pan, isMuted: false });
          lastMarkerTrigger.current[m.id] = time;
        }
      });
    }

    setCurrentTime(time);
    prevTimeRef.current = time;
    requestRef.current = requestAnimationFrame(sync);
  }, [isPlaying, markers, ambientLayers, anySoloActive, recomputePlayback]);

  useEffect(() => {
    if (isPlaying) requestRef.current = requestAnimationFrame(sync);
    else if (requestRef.current) cancelAnimationFrame(requestRef.current);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [isPlaying, sync]);

  const togglePlay = () => {
    const next = !isPlaying;
    setIsPlaying(next);
    if (videoRef.current) {
      if (next) {
        audioEngine.resume();
        videoRef.current.play();
        recomputePlayback(videoRef.current.currentTime);
      } else {
        videoRef.current.pause();
        audioEngine.stopAll();
      }
    }
  };

  const seekTo = (t: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = t;
      if (isPlaying) recomputePlayback(t);
    } 
    setCurrentTime(t); 
    prevTimeRef.current = t; 
  };

  const activeMarker = useMemo(() => markers.find(m => m.id === activeTargetId), [markers, activeTargetId]);

  return (
    <div className="flex flex-col lg:flex-row h-screen w-screen bg-[#fbfaf7] text-[#171717] overflow-hidden font-sans select-none">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      <WelcomeModal isOpen={isWelcomeOpen} onClose={() => setIsWelcomeOpen(false)} />

      <aside className="w-full lg:w-[420px] h-full bg-[#fbfaf7] border-r-[1.5px] border-[#d1cabc] flex flex-col z-20 shrink-0 overflow-hidden">
        <div ref={sidebarRef} className="flex-1 overflow-y-auto dark-scrollbar px-6 lg:px-10 pt-10 pb-12 scroll-smooth">
          <div className="flex justify-between items-end gap-4 mb-10">
            <div className="shrink-0">
              <MondoLogo className="block" /> 
            </div>
            <div className="flex flex-col gap-2.5 w-[110px] shrink-0">
              <PillButton variant="beige" onClick={handleSelectMedia} icon={<MediaIcon />} className="w-full">Media</PillButton>
              <SessionManager 
                data={{ media, ambientLayers, markers, masterVolume, sourceVolume, genMode }} 
                onLoad={(s) => {
                  setMedia(s.media || null);
                  setAmbientLayers(s.ambientLayers);
                  setMarkers(s.markers);
                  setMasterVolume(s.masterVolume);
                  setSourceVolume(s.sourceVolume);
                  setGenMode(s.genMode);
                  addToast("Project Loaded", "Success");
                }} 
              />
              <PillButton 
                variant="beige" 
                onClick={() => { if (!hasGeneratedAudio) { addToast("Synthesize audio before exporting stems", "Error"); return; } exportStems(duration, ambientLayers, markers); }} 
                icon={<StemIcon />} 
                className={`w-full ${!hasGeneratedAudio ? 'opacity-40 grayscale cursor-help' : ''}`}
              >Stems</PillButton>
            </div>
          </div>

          <section className="mb-10">
            <SectionLabel className="mb-2">GENERATION MODEL</SectionLabel>
            <SegmentedToggle value={genMode} onChange={v => setGenMode(v as any)} items={[{ value: 'fast', label: 'OMNI FLASH' }, { value: 'high', label: 'VEO 3.1 - FAST' }]} />
          </section>

          <section className="mb-10">
            <SectionLabel className="mb-2">SCENE TOOLS</SectionLabel>
            <div className="flex flex-col gap-3">
              <PillButton variant="green" onClick={addAmbience} className={!isInitialized ? 'opacity-40 grayscale pointer-events-auto cursor-help' : ''}>Ambiance</PillButton>
              <div className="flex gap-3">
                <PillButton variant="orange" className={`flex-1 ${!isInitialized ? 'opacity-40 grayscale pointer-events-auto cursor-help' : ''}`} onClick={addFoley}>Foley</PillButton>
                <PillButton variant="purple" className={`flex-1 ${!isInitialized ? 'opacity-40 grayscale pointer-events-auto cursor-help' : ''}`} onClick={addSFX}>SFX</PillButton>
              </div>
              <SoundKey />
            </div>
          </section>

          <div className="space-y-8 mt-8 pb-32">
            {ambientLayers.map(l => (
              <SoundStem 
                id={l.id}
                key={l.id} 
                layer={l} 
                onUpdate={u => updateAmbientLayer(l.id, u)} 
                onGenerate={() => handleGenerateAmbience(l.id, l.prompt, l.environment, l.mic, l.soundCharacter)}
                onDelete={() => { audioEngine.stop(l.id); setAmbientLayers(p => p.filter(o => o.id !== l.id)); addToast("Track Removed", "Success"); }}
                onDuplicate={() => handleDuplicateLayer(l)}
                isBusy={isBusy}
                activeSolo={anySoloActive} />
            ))}
            {markers.map(m => (
              <MarkerItem 
                id={m.id}
                key={m.id} 
                marker={m} 
                onUpdate={u => updateMarker(m.id, u)}
                onTarget={() => setActiveTargetId(m.id)}
                onDuplicate={() => handleDuplicateMarker(m)}
                onGenerate={() => handleGenerateMarker(m.id, m.type, m.prompt, m.environment, m.mic, m.sfxMode, m.soundCharacter, m.focusArea)}
                onDelete={() => { audioEngine.stop(m.id); setMarkers(p => p.filter(o => o.id !== m.id)); addToast("Channel Removed", "Success"); }}
                activeSolo={anySoloActive} />
            ))}
          </div>
        </div>

        <div className="px-6 lg:px-10 py-8 bg-[#fbfaf7] border-t-[1.5px] border-[#d1cabc] space-y-6 shrink-0">
          <div className="flex items-center gap-5">
            <div className="flex-1 space-y-4">
              <RangeSlider label="Media Reference" value={sourceVolume} min={0} max={100} onChange={setSourceVolume} />
              <RangeSlider label="Master" value={masterVolume} min={0} max={120} onChange={setMasterVolume} />
              <ControlKey />
            </div>
            <MasterMeter isBusy={isBusy} />
          </div>
          <div className="flex flex-col gap-4">
            <button 
              onClick={() => { if(validateInteraction()) renderMaster(media, ambientLayers, markers, masterVolume, sourceVolume, includeMaster) }} 
              disabled={isBusy} 
              className={`w-full h-[64px] lg:h-[78px] bg-[#171717] text-white rounded-full font-medium uppercase text-[14px] lg:text-[16px] tracking-[0.05em] shadow-xl hover:scale-[1.02] active:scale-100 transition-all flex items-center justify-center gap-3 cursor-pointer shrink-0 ${!isInitialized ? 'opacity-20 grayscale pointer-events-auto cursor-help' : ''}`}
            >
              {isBusy ? <span className="material-symbols-outlined animate-spin text-[24px]">refresh</span> : <span className="material-symbols-outlined text-[24px]">download</span>}
              {isBusy ? status : 'Export Final Video'}
            </button>
            <label className="flex items-start gap-3 px-2 cursor-pointer group">
              <div className="pt-0.5">
                <div className={`w-4 h-4 rounded border-[1.5px] border-[#17171740] flex items-center justify-center transition-colors ${includeMaster ? 'bg-[#c98b00] border-[#c98b00]' : 'bg-transparent group-hover:border-[#17171760]'}`}>
                  {includeMaster && <span className="material-symbols-outlined text-white text-[12px] font-bold">check</span>}
                </div>
                <input type="checkbox" className="hidden" checked={includeMaster} onChange={() => setIncludeMaster(!includeMaster)} />
              </div>
              <span className="text-[10px] text-[#17171740] font-medium uppercase tracking-[0.1em] leading-tight group-hover:text-[#17171760] transition-colors">
                Include Master File: Bounces all active layers into a single high-fidelity studio master file.
              </span>
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col bg-[#fbfaf7] relative overflow-hidden min-h-0">
        <div className="flex-1 flex items-center justify-center p-4 lg:p-10 relative min-h-0 overflow-hidden">
          <div className="w-full h-full max-w-[1280px] aspect-video bg-[#fbfaf7] rounded-[24px] lg:rounded-[40px] overflow-hidden border border-[#17171710] relative shadow-2xl flex items-center justify-center">
            {media ? (
              <video ref={videoRef} src={`data:${media.mimeType};base64,${media.base64}`} className="w-full h-full object-contain" onLoadedMetadata={(e) => setDuration(e.currentTarget.duration)} loop crossOrigin="anonymous" />
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-[#17171705]">
                <span className="material-symbols-outlined text-[100px] lg:text-[140px]">videocam</span>
                <p className="text-[14px] lg:text-[16px] font-medium uppercase tracking-[0.4em] mt-8">NO SIGNAL</p>
              </div>
            )}
            {activeTargetId && <AreaSelector area={activeMarker?.focusArea} onChange={(area) => setMarkers(p => p.map(m => m.id === activeTargetId ? {...m, focusArea: area} : m))} onClose={() => setActiveTargetId(null)} />}
          </div>
        </div>
        <div className="shrink-0 bg-[#fbfaf7] border-t-[1.5px] border-[#d1cabc] px-4 lg:px-[60px] pt-6 pb-8 flex flex-col gap-6">
          <div className="h-[220px] lg:h-[280px]">
            <Timeline 
              currentTime={currentTime} 
              duration={duration} 
              markers={markers} 
              ambientLayers={ambientLayers}
              anySoloActive={anySoloActive}
              onSeek={seekTo} 
              onMarkerUpdate={(id, up) => updateMarker(id, up)}
              onLayerUpdate={(id, up) => updateAmbientLayer(id, up)}
            />
          </div>
          <div className="flex items-center justify-center gap-4 relative">
            <button onClick={() => seekTo(0)} disabled={!media} className="w-[54px] lg:w-[64px] h-[48px] lg:h-[58px] rounded-full bg-white border-[1.5px] border-[#171717] flex items-center justify-center text-[#171717] hover:bg-[#171717] hover:text-white transition-all disabled:opacity-20 cursor-pointer shadow-sm"><span className="material-symbols-outlined text-[36px] lg:text-[46px]">first_page</span></button>
            <button onClick={togglePlay} disabled={!media} className={`w-[54px] lg:w-[64px] h-[48px] lg:h-[58px] rounded-full border-[1.5px] border-[#171717] flex items-center justify-center transition-all disabled:opacity-20 cursor-pointer shadow-sm ${isPlaying ? 'bg-[#171717] text-white' : 'bg-white text-[#171717]'}`}>
              <span className="material-symbols-outlined text-[36px] lg:text-[46px]">{isPlaying ? 'pause' : 'play_arrow'}</span>
            </button>
            <div className="absolute right-0 font-medium text-[16px] lg:text-[18px] tabular-nums tracking-widest opacity-30">{currentTime.toFixed(3)}S</div>
          </div>
        </div>
      </main>
    </div>
  );
}

import React, { useState, useRef, useEffect, FC } from 'react';

