export const InfoTooltip: FC<{ text: string }> = ({ text }) => (
  <div className="group relative inline-block ml-1 align-baseline">
    <span className="material-symbols-outlined text-[12px] opacity-30 group-hover:opacity-100 transition-opacity cursor-help">
      info
    </span>
    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover:block w-[180px] p-2 bg-[#171717] text-white text-[10px] font-medium rounded-lg shadow-xl z-50 animate-in fade-in zoom-in-95 duration-200">
      <div className="relative">
        {text}
        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-[#171717]" />
