export const PillButton: FC<{
 icon?: React.ReactNode; children: React.ReactNode; 
 variant?: 'obsidian' | 'beige' | 'orange' | 'purple' | 'solid' | 'green';
 onClick?: () => void; disabled?: boolean; className?: string;
}> = ({ icon, children, variant = 'obsidian', onClick, disabled, className = '' }) => {
 const base = 'group flex items-center justify-center h-[44px] rounded-full tracking-[0.5px] transition-all duration-200 cursor-pointer active:scale-[0.97] disabled:opacity-30 disabled:cursor-not-allowed select-none';
 const styles = {
   obsidian: 'bg-[#171717] text-white text-[13px] font-medium px-6 shadow-md hover:bg-[#2a2a2a]',
   beige: 'bg-[#d0cabf] text-[#1A1A1A] text-[13px] font-medium px-6 shadow-sm hover:bg-[#c0b9ad]',
   green: 'bg-[#009d50] text-white text-[13px] font-medium px-6 shadow-md hover:brightness-110',
   orange: 'bg-[#ed7235] text-white text-[13px] font-medium px-6 shadow-md hover:brightness-110',
   purple: 'bg-[#a696f8] text-white text-[13px] font-medium px-6 shadow-md hover:brightness-110',
   solid: 'bg-white text-black border-2 border-[#151515] px-6 font-medium text-[13px]'
 };
 return (
   <button className={`${base} ${styles[variant]} ${className}`} onClick={onClick} disabled={disabled}>
     {icon && <span className="mr-2 flex items-center justify-center scale-90">{icon}</span>}
     <span className="whitespace-nowrap uppercase tracking-wider">{children}</span>
   </button>
 );
};

export const SegmentedToggle: FC<{ 
  value: string; 
  items: { value: string; label: string }[]; 
  onChange: (v: string) => void 
}> = ({ value, items, onChange }) => (
  <div 
    className="w-full h-[44px] rounded-full overflow-hidden grid border-[1.5px] border-[#11111115] bg-[#1111110d] p-0"
    style={{ gridTemplateColumns: `repeat(${items.length}, minmax(0, 1fr))` }}
  >
    {items.map(i => {
      const isSelected = value === i.value;
      const activeColor = 'bg-[#c49040]';
      const activeTextColor = 'text-white';

      return (
        <button 
          key={i.value} 
          onClick={() => onChange(i.value)} 
          className={`font-medium text-[13px] tracking-wider uppercase transition-all duration-200 cursor-pointer h-full ${isSelected ? `${activeColor} ${activeTextColor} shadow-inner` : 'bg-white text-[#171717] opacity-60 hover:opacity-80'}`}
        >
          {i.label}
        </button>
      );
    })}
  </div>
);

export const RangeSlider: FC<{
 label: string; value: number; min: number; max: number;
 onChange: (v: number) => void; formatValue?: (v: number) => string;
}> = ({ label, value, min, max, onChange, formatValue }) => {
 const percent = ((value - min) / (max - min)) * 100;
 return (
   <div className="flex flex-col gap-2 w-full">
     <div className="flex items-center justify-between px-1 select-none uppercase">
       <span className="text-[#111111] font-medium ml-[20px] text-[14px] tracking-[0.05em]">{label}</span>
       <span className="text-[#c98b00] font-medium text-[14px] tracking-[0.05em]">{formatValue ? formatValue(value) : value}</span>
     </div>
     <div className="w-full flex items-center h-4">
       <input type="range" min={min} max={max} value={value} step={1} onChange={e => onChange(Number(e.target.value))} className="w-full h-[13px] rounded-full appearance-none cursor-pointer outline-none" style={{ WebkitAppearance: 'none', background: `linear-gradient(to right, #c98b00 0%, #c98b00 ${percent}%, #151515 ${percent}%, #151515 100%)` }} />
       <style>{`
         input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 32px; height: 32px; border-radius: 50%; background: #c98b00; border: none; cursor: pointer; }
         input[type=range]::-moz-range-thumb { width: 32px; height: 32px; border: none; border-radius: 50%; background: #c98b00; cursor: pointer; }
       `}</style>
     </div>
   </div>
 );
};

export const MondoSlider: FC<{ 
  label: string; 
  value: number; 
  min?: number; 
  max?: number; 
  onChange: (v: number) => void; 
  formatValue?: (v: number) => string;
  tooltip?: string;
}> = ({ label, value, min = 0, max = 100, onChange, formatValue, tooltip }) => {
 const percent = ((value - min) / (max - min)) * 100;
 return (
   <div className="flex flex-col gap-1 w-full">
     <div className="flex items-center justify-between px-1 select-none">
       <div className="flex items-center">
         <span className="text-[10px] font-medium text-[#171717] tracking-widest uppercase opacity-40 leading-none">{label}</span>
         {tooltip && <InfoTooltip text={tooltip} />}
       </div>
       <span className="text-[11px] font-medium text-[#171717] leading-none">{formatValue ? formatValue(value) : value}</span>
     </div>
     <div className="w-full flex items-center h-2">
       <input type="range" min={min} max={max} value={value} onChange={e => onChange(Number(e.target.value))} className="w-full h-[4px] rounded-full appearance-none cursor-pointer outline-none bg-[#17171715]" style={{ WebkitAppearance: 'none', background: `linear-gradient(to right, #171717 ${percent}%, #17171715 ${percent}%)` }} />
       <style>{`
         input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border-radius: 50%; background: #171717; border: none; cursor: pointer; }
         input[type=range]::-moz-range-thumb { width: 12px; height: 12px; border: none; border-radius: 50%; background: #171717; cursor: pointer; }
       `}</style>
     </div>
   </div>
 );
};

export const FieldDropdown: FC<{ label: string; value: string; options: string[]; onChange: (val: string) => void; className?: string; }> = ({ label, value, options, onChange, className = '' }) => {
 const [isOpen, setIsOpen] = useState(false);
 const ref = useRef<HTMLDivElement>(null);
 useEffect(() => {
   const handler = (e: any) => { if (ref.current && !ref.current.contains(e.target)) setIsOpen(false); };
   document.addEventListener('mousedown', handler);
   return () => document.removeEventListener('mousedown', handler);
 }, []);
 return (
   <div ref={ref} className={`relative ${className}`}>
     <button type="button" onClick={() => setIsOpen(!isOpen)} className="w-full text-left border-2 border-[#151515] transition-colors rounded-xl flex flex-col justify-center h-[60px] px-4 select-none focus:outline-none bg-white/50 cursor-pointer">
       <p className="text-[10px] font-medium text-[#171717] tracking-widest uppercase opacity-40">{label}</p>
       <div className="flex items-center justify-between">
         <span className="text-[14px] font-medium text-[#171717]">{value}</span>
         <span className={`material-symbols-outlined text-[20px] text-[#171717] transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
       </div>
     </button>
     {isOpen && (
       <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#fbfaf7] border-2 border-[#151515] rounded-xl overflow-hidden shadow-2xl animate-dropdown origin-top-left">
         <div className="max-h-60 overflow-y-auto dark-scrollbar">
           {options.map((opt) => (
             <button key={opt} type="button" className={`w-full text-left px-4 py-3 text-[14px] font-medium hover:bg-[#151515]/5 transition-colors cursor-pointer ${value === opt ? 'bg-[#151515] text-white' : 'text-[#171717]'}`} onClick={() => { onChange(opt); setIsOpen(false); }}>{opt}</button>
           ))}
         </div>
       </div>
     )}
   </div>
 );
};

import React from 'react';
import { Marker, SoundCharacter } from '../types';
import { MondoSlider, FieldDropdown, InfoTooltip } from './Primitives';
import { SourceTrimmer } from './SourceTrimmer';
import { SOUND_CHARACTERS, CHARACTER_PRESETS } from '../constants';

export const MarkerItem: React.FC<{
 id?: string; marker: Marker; onUpdate: (up: Partial<Marker>) => void; onTarget: () => void; onGenerate: () => void; onDelete: () => void; onDuplicate: () => void; activeSolo: boolean;
}> = ({ id, marker, onUpdate, onTarget, onGenerate, onDelete, onDuplicate, activeSolo }) => {
 const isBusy = marker.status === 'generating' || marker.status === 'processing';
 const isDim = marker.isMuted || (activeSolo && !marker.isSolo);
 const typeAccent = marker.type === 'Foley' ? '#ed7235' : '#a696f8';

 const handleCharacterChange = (val: string) => {
   const char = val as SoundCharacter;
   const preset = CHARACTER_PRESETS[char];
   onUpdate({ soundCharacter: char, environment: preset.env, mic: preset.mic });
 };

 const formatPan = (v: number) => {
   if (v < 0) return `L${Math.abs(v)}`;
   if (v > 0) return `R${v}`;
   return '0';
 };

 return (
   <div id={id} className={`w-full border-[1.5px] border-[#171717] rounded-[20px] bg-[#f4f2ee] p-[24px_20px] space-y-6 transition-all relative ${isDim ? 'opacity-30 grayscale-[0.5]' : 'shadow-lg'}`}>
     <div className="flex items-center justify-between">
       <div className="flex items-center gap-3">
         <div className="w-[10px] h-[10px] rounded-full" style={{ backgroundColor: typeAccent }} />
         <div className="font-medium text-[14px] leading-tight text-[#171717] tracking-tight">{marker.type}<br />Processor</div>
       </div>
       <div className="flex items-center gap-[10px]">
         <div className="group relative">
           <button className="w-[28px] h-[28px] rounded-full border-[1.5px] border-[#171717] flex items-center justify-center hover:bg-[#171717] hover:text-white transition-all cursor-pointer" onClick={onTarget}><span className="material-symbols-outlined text-[16px]">crop_free</span></button>
           <div className="absolute -bottom-7 left-1/2 -translate-x-1/2 hidden group-hover:block px-2 py-0.5 bg-[#171717] text-white text-[8px] font-black uppercase tracking-widest rounded whitespace-nowrap z-50">Focus</div>
         </div>

         <div className="group relative">
           <button className="w-[28px] h-[28px] rounded-full border-[1.5px] border-[#171717] flex items-center justify-center hover:bg-[#171717] hover:text-white transition-all cursor-pointer" onClick={onDuplicate}><span className="material-symbols-outlined text-[16px]">content_copy</span></button>
           <div className="absolute -bottom-7 left-1/2 -translate-x-1/2 hidden group-hover:block px-2 py-0.5 bg-[#171717] text-white text-[8px] font-black uppercase tracking-widest rounded whitespace-nowrap z-50">Duplicate</div>
         </div>

         <div className="group relative">
           <button onClick={() => onUpdate({ isMuted: !marker.isMuted })} className={`w-[28px] h-[28px] rounded-full font-medium text-[14px] flex items-center justify-center border-[1.5px] border-[#171717] cursor-pointer transition-colors ${marker.isMuted ? 'bg-[#ff6818] text-white' : 'bg-[#d0cabf] text-[#171717]'}`}>M</button>
           <div className="absolute -bottom-7 left-1/2 -translate-x-1/2 hidden group-hover:block px-2 py-0.5 bg-[#171717] text-white text-[8px] font-black uppercase tracking-widest rounded whitespace-nowrap z-50">Mute</div>
         </div>

         <div className="group relative">
           <button onClick={() => onUpdate({ isSolo: !marker.isSolo })} className={`w-[28px] h-[28px] rounded-full font-medium text-[14px] flex items-center justify-center border-[1.5px] border-[#171717] cursor-pointer transition-colors ${marker.isSolo ? 'bg-[#be8300] text-white' : 'bg-[#d0cabf] text-[#171717]'}`}>S</button>
           <div className="absolute -bottom-7 left-1/2 -translate-x-1/2 hidden group-hover:block px-2 py-0.5 bg-[#171717] text-white text-[8px] font-black uppercase tracking-widest rounded whitespace-nowrap z-50">Solo</div>
         </div>

         <button onClick={onDelete} className="ml-2 opacity-20 hover:opacity-100 transition-opacity cursor-pointer"><span className="material-symbols-outlined text-[20px]">close</span></button>
       </div>
     </div>

     <textarea
       value={marker.prompt}
       onChange={e => onUpdate({ prompt: e.target.value })}
       placeholder={`DESCRIBE ${marker.type.toUpperCase()} EVENT...`}
       className="w-full bg-[#e7e0d3] border-[1.5px] border-[#17171710] rounded-[12px] px-4 py-3 text-[12px] font-medium h-[80px] resize-none outline-none transition-all placeholder:opacity-30 focus:border-[#17171720]"
     />

     <button
       onClick={onGenerate}
       disabled={isBusy}
       className="w-full h-[43px] rounded-full font-medium text-[14px] flex items-center justify-center gap-3 border-[1.5px] border-[#171717] shadow-sm hover:scale-[1.01] active:scale-95 disabled:opacity-50 cursor-pointer"
       style={{ backgroundColor: typeAccent, color: 'white' }}
     >
       <span className="material-symbols-outlined text-[20px]">{isBusy ? 'pending' : 'refresh'}</span>
       {isBusy ? 'Synthesizing...' : 'Generate'}
     </button>

     <div className="space-y-[10px]">
       <FieldDropdown label="Sound Character" value={marker.soundCharacter} options={SOUND_CHARACTERS} onChange={handleCharacterChange} />
     </div>

     <div className="space-y-6 pt-2">
       <MondoSlider 
         label="Gain Level" 
         value={marker.volume} 
         onChange={v => onUpdate({ volume: v })} 
         tooltip="Adjusts the output volume of this specific sound layer."
       />
       <MondoSlider 
         label="Signal Pan" 
         value={marker.pan} 
         min={-100} max={100} 
         onChange={v => onUpdate({ pan: v })} 
         formatValue={formatPan} 
         tooltip="Positions the sound in the stereo field from Left (-100) to Right (100)."
       />
     </div>

     <div className="space-y-3">
