export const Timeline: React.FC<{
  currentTime: number; 
  duration: number; 
  markers: Marker[];
  ambientLayers: SoundLayer[];
  anySoloActive: boolean;
  onSeek: (time: number) => void; 
  onMarkerUpdate: (id: string, up: Partial<Marker>) => void;
  onLayerUpdate: (id: string, up: Partial<SoundLayer>) => void;
}> = ({ currentTime, duration, markers, ambientLayers, anySoloActive, onSeek, onMarkerUpdate, onLayerUpdate }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [containerWidth, setContainerWidth] = useState(0);
  const total = duration || 8;

  // Track container width reactively for pixel-to-time calculations
  useLayoutEffect(() => {
    if (scrollContainerRef.current) {
      setContainerWidth(scrollContainerRef.current.clientWidth);
    }
  }, []);

  useEffect(() => {
    if (!scrollContainerRef.current) return;
    const observer = new ResizeObserver(entries => {
      if (entries[0]) {
        setContainerWidth(entries[0].contentRect.width);
      }
    });
    observer.observe(scrollContainerRef.current);
    return () => observer.disconnect();
  }, []);

  const toggleGroup = (id: string) => {
    const next = new Set(collapsedGroups);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setCollapsedGroups(next);
  };

  const foleyMarkers = useMemo(() => markers.filter(m => m.type === 'Foley'), [markers]);
  const sfxMarkers = useMemo(() => markers.filter(m => m.type === 'SFX'), [markers]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    const rect = scrollContainerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const contentWidth = scrollContainerRef.current.clientWidth;
    onSeek((x / contentWidth) * total);
  };

  const ticks = useMemo(() => {
    const arr = [];
    const step = total > 30 ? 5 : 1;
    for (let i = 0; i <= total; i += step) arr.push(i);
    return arr;
  }, [total]);

  const pixelsPerSecond = useMemo(() => {
    const width = containerWidth || 1000;
    return width / total;
  }, [total, containerWidth]);

  return (
    <div className="w-full h-full flex flex-col bg-[#d2cabb] border-[1.5px] border-[#171717] rounded-[24px] overflow-hidden shadow-inner transition-all duration-300 relative">

      {/* Unified Scroll Viewport */}
      <div 
        ref={scrollContainerRef}
        className="flex-1 overflow-y-auto dark-scrollbar" 
        style={{ scrollbarGutter: 'stable' }}
      >
        {/* Content Wrapper to define the relative height for the playhead line */}
        <div className="relative min-h-full">

          {/* Sticky Ruler Background & Ticks */}
          <div 
            className="sticky top-0 h-10 border-b border-[#17171720] bg-[#d2cabb] z-40 cursor-pointer select-none"
            onClick={handleTimelineClick}
          >
            {ticks.map(t => (
              <div 
                key={t} 
                className="absolute top-0 bottom-0 border-l border-[#17171715]" 
                style={{ left: `${(t / total) * 100}%` }}
              >
                <span className="absolute top-1 left-1 text-[9px] font-bold opacity-40">{t}s</span>
              </div>
            ))}
          </div>

          {/* Tracks List */}
          <div className="flex flex-col min-h-[200px]">
            {/* Ambiance Group */}
            <TimelineGroup 
              title="Ambiance" 
              count={ambientLayers.length} 
              isCollapsed={collapsedGroups.has('ambiance')} 
              onToggle={() => toggleGroup('ambiance')}
              accentColor="#009d50"
            >
              {ambientLayers.map((l, idx) => (
                <div key={l.id} className="h-12 border-b border-[#17171708] relative group hover:bg-[#17171703] transition-colors">
                  <div className="absolute left-2 top-1 z-10 text-[8px] font-bold opacity-20 group-hover:opacity-40 uppercase tracking-tighter">Track {idx + 1}</div>
                  {l.audioBase64 && (
                    <AudioClip 
                      item={l} 
                      duration={total} 
                      pixelsPerSecond={pixelsPerSecond}
                      anySoloActive={anySoloActive}
                      onUpdate={(up) => onLayerUpdate(l.id, up)}
                      accentColor="#009d50"
                    />
                  )}
                </div>
              ))}
              {ambientLayers.length === 0 && <div className="h-8 flex items-center px-6 text-[9px] font-medium opacity-20 uppercase tracking-widest italic">No layers added</div>}
            </TimelineGroup>

            {/* Foley Group */}
            <TimelineGroup 
              title="Foley" 
              count={foleyMarkers.length} 
              isCollapsed={collapsedGroups.has('foley')} 
              onToggle={() => toggleGroup('foley')}
              accentColor="#ed7235"
            >
              {foleyMarkers.map((m, idx) => (
                <div key={m.id} className="h-12 border-b border-[#17171708] relative group hover:bg-[#17171703] transition-colors">
                  <div className="absolute left-2 top-1 z-10 text-[8px] font-bold opacity-20 group-hover:opacity-40 uppercase tracking-tighter">Track {idx + 1}</div>
                  {m.audioBase64 && (
                    <AudioClip 
                      item={m}
                      duration={total}
                      pixelsPerSecond={pixelsPerSecond}
                      anySoloActive={anySoloActive}
                      onUpdate={(up) => onMarkerUpdate(m.id, up)}
                      accentColor="#ed7235"
                    />
                  )}
                </div>
              ))}
              {foleyMarkers.length === 0 && <div className="h-8 flex items-center px-6 text-[9px] font-medium opacity-20 uppercase tracking-widest italic">No events generated</div>}
            </TimelineGroup>

            {/* SFX Group */}
            <TimelineGroup 
              title="SFX" 
              count={sfxMarkers.length} 
              isCollapsed={collapsedGroups.has('sfx')} 
              onToggle={() => toggleGroup('sfx')}
              accentColor="#a696f8"
            >
              {sfxMarkers.map((m, idx) => (
                <div key={m.id} className="h-12 border-b border-[#17171708] relative group hover:bg-[#17171703] transition-colors">
                  <div className="absolute left-2 top-1 z-10 text-[8px] font-bold opacity-20 group-hover:opacity-40 uppercase tracking-tighter">Track {idx + 1}</div>
                  {m.audioBase64 && (
                    <AudioClip 
                      item={m}
                      duration={total}
                      pixelsPerSecond={pixelsPerSecond}
                      anySoloActive={anySoloActive}
                      onUpdate={(up) => onMarkerUpdate(m.id, up)}
                      accentColor="#a696f8"
                    />
                  )}
                </div>
              ))}
              {sfxMarkers.length === 0 && <div className="h-8 flex items-center px-6 text-[9px] font-medium opacity-20 uppercase tracking-widest italic">No events generated</div>}
            </TimelineGroup>
          </div>

          {/* Unified Playhead System */}
          <div 
            className="absolute top-0 bottom-0 pointer-events-none z-50 w-0"
            style={{ left: `${(currentTime / total) * 100}%` }}
          >
            {/* Vertical Playhead Line: Tied to content height */}
            <div className="absolute top-0 bottom-0 w-[2px] bg-[#171717] -translate-x-1/2" />

            {/* Sticky Playhead Handle: Tied to viewport top */}
            <div className="sticky top-0 z-60 pointer-events-none h-0">
              <div className="absolute top-0 -translate-x-1/2 w-3 h-3 bg-[#171717] rounded-full shadow-lg" />
            </div>
          </div>
        </div>
      </div>

      {/* Footer / Summary */}
      <div className="h-8 bg-[#17171708] flex items-center justify-between px-6 shrink-0">
        <div className="flex gap-4">
           <div className="flex items-center gap-2">
             <span className="text-[8px] font-black uppercase tracking-widest text-[#17171740]">Individual Track Engine</span>
           </div>
        </div>
        <div className="text-[9px] font-bold text-[#17171740] uppercase tracking-tighter">
          {ambientLayers.length + markers.length} Total Channels
        </div>
      </div>
    </div>
  );
};

