import React, { useEffect, useState, useRef } from 'react';
import { audioEngine } from '../services/audioEngine';

export const MasterMeter: React.FC<{ isBusy?: boolean }> = ({ isBusy }) => {
  const [level, setLevel] = useState(0);
  const requestRef = useRef<number>(null);

  // High-frequency sampling for smooth animation
  useEffect(() => {
    const update = () => {
      const rawLevel = audioEngine.getMasterLevel();
      // Apply a fast peak-rise and slow fall for better visibility
      setLevel(prev => {
        if (rawLevel > prev) return rawLevel;
        return prev * 0.92; // Decay
      });
      requestRef.current = requestAnimationFrame(update);
    };

    requestRef.current = requestAnimationFrame(update);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  // Increase resolution to 24 segments for professional precision
  const segmentCount = 24;
  const activeCount = Math.floor(level * segmentCount);

  return (
    <div className="flex items-center gap-2">
      <div className={`w-[24px] h-[150px] rounded-[4px] bg-[#171717] flex flex-col justify-center gap-[2px] p-[8px_5px] border-[2px] border-[#171717] shadow-xl relative overflow-hidden ${isBusy ? 'animate-pulse' : ''}`}>
        {/* Glow effect overlay */}
        <div className="absolute inset-0 bg-gradient-to-b from-white/5 to-transparent pointer-events-none" />

        {Array.from({ length: segmentCount }).map((_, i) => {
          // segments light up from bottom to top
          const isActive = activeCount > (segmentCount - 1 - i);

          // Color zones: 
          // Top 4: Red/Orange (Peak)
          // Middle 8: Yellow/Amber (Warn)
          // Bottom: Studio Green
          let activeColor = '#459a58'; // Green
          if (i < 4) activeColor = '#ff3b30'; // Red
          else if (i < 12) activeColor = '#fff200'; // Yellow

          return (
            <span 
              key={i} 
              className="h-[4px] block rounded-[0.5px] transition-all duration-75" 
              style={{ 
                backgroundColor: isActive ? activeColor : 'rgba(255,255,255,0.03)',
                boxShadow: isActive ? `0 0 10px ${activeColor}80` : 'none',
                opacity: isActive ? 1 : 0.5
              }} 
            />
          );
        })}
      </div>
    </div>
  );
};

import { useState, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import JSZip from 'jszip';
import { ffmpegService } from '../services/ffmpegService';
import { SoundLayer, Marker, LayerType, AcousticEnv, MicStyle, SFXMode, SoundCharacter } from '../types';
import { CHARACTER_PRESETS } from '../constants';

async function uint8ToBase64(arr: Uint8Array): Promise<string> {
  const blob = new Blob([arr]);
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(blob);
  });
}

function extractWaveform(data: Uint8Array, points: number = 60): number[] {
  try {
    const samples = new Int16Array(data.buffer, 44);
    const step = Math.floor(samples.length / points);
    const result = [];
    for (let i = 0; i < points; i++) {
      let max = 0;
      for (let j = 0; j < step; j++) {
        const val = Math.abs(samples[i * step + j] || 0);
        if (val > max) max = val;
      }
      result.push(Math.min(1, max / 28000)); 
    }
    return result;
  } catch (e) { return Array(points).fill(0.1); }
}

export function useSoundEngine() {
  const [isBusy, setIsBusy] = useState(false);
  const [status, setStatus] = useState('Ready');

  const generateAudio = useCallback(async (
    prompt: string, 
    mode: 'fast' | 'high', 
    type: LayerType, 
    env: AcousticEnv, 
    mic: MicStyle,
    referenceImageId?: string,
    isFocused: boolean = false,
    sfxMode?: SFXMode,
    character?: SoundCharacter
  ) => {
    const model = mode === 'fast' ? 'Omni Flash' : 'Veo 3.1 - Fast';

    const charDesc = character ? CHARACTER_PRESETS[character].desc : null;

    const envDesc = {
      'Studio': 'recorded in a dry isolation booth, no reverb',
      'Warehouse': 'large industrial warehouse with metallic echoes',
      'Chamber': 'tight anachoic chamber, extremely dry and direct',
      'Field': 'open air, natural exterior acoustics',
      'Forest': 'natural woodland acoustics, slight organic diffusion',
      'Small Room': 'intimate room acoustics, domestic feel',
      'Underwater': 'muffled, hydrophone style, sub-aquatic density'
    }[env];

    const micDesc = {
      'Condenser': 'high fidelity studio condenser microphone, crisp details',
      'Shotgun': 'highly directional shotgun mic, focused on the source',
      'Binaural': 'immersive 3D binaural recording, spatial depth',
      'Dynamic': 'rugged dynamic mic, warm mids, focused',
      'Vintage': 'vintage warm tape saturation, analog character',
      'Phone': 'lo-fi mobile phone microphone, limited frequency response'
    }[mic];

    const sonicSignature = charDesc || `${envDesc}. Captured with ${micDesc}`;

    let finalPrompt = '';
    if (type === 'Ambience') {
      finalPrompt = `TECHNICAL MATERIAL STUDY / REFERENCE SHOT. ${prompt}. ${sonicSignature}. SINGLE CONTINUOUS SHOT, FIXED CAMERA, LOCKED-OFF WIDE SHOT, NO CUTS. Pure atmospheric textural layers. Avoid montage, multi-cam, or scene transitions. No creative editing.`;
    } else if (type === 'SFX' && sfxMode === 'Designed') {
      finalPrompt = `DESIGNED ABSTRACT SFX. Internal sound synthesis. ${prompt}. High-end cinematic sound design. Elements: whoosh, shimmer, impact, riser. ${sonicSignature}. Pure professional sonic texture, no background noise.`;
    } else {
      const isolationPrefix = isFocused 
        ? "ISOLATED OBJECT SOUND. Focus ONLY on the visual content of the provided image crop. ZERO background noise." 
        : "SOLO FOLEY SOUND EFFECT.";

      finalPrompt = `${isolationPrefix} ${prompt}. ${sonicSignature}. Pure direct sound.`;
    }

    setIsBusy(true);
    setStatus('Analyzing Scene...');
    try {
      const refIds = (type === 'SFX' && sfxMode === 'Designed') ? undefined : (referenceImageId ? [referenceImageId] : undefined);

      const result = await Flow.generate.video({
        prompt: finalPrompt,
        modelDisplayName: model,
        durationSeconds: 8,
        referenceImageMediaIds: refIds,
        aspectRatio: '16:9'
      });

      setStatus('Processing Audio...');
      const bytes = Uint8Array.from(atob(result.base64), c => c.charCodeAt(0));
      const vFile = `v_${Date.now()}.mp4`, wFile = `a_${Date.now()}.wav`;
      await ffmpegService.writeFile(vFile, bytes);
      await ffmpegService.exec(['-i', vFile, '-vn', '-acodec', 'pcm_s16le', '-ar', '44100', '-ac', '2', '-y', wFile]);
      const wav = await ffmpegService.readFile(wFile) as Uint8Array;

      const waveform = extractWaveform(wav);
      const base64 = await uint8ToBase64(wav);
      const url = URL.createObjectURL(new Blob([wav.buffer], { type: 'audio/wav' }));

      setStatus('Ready');
      return { url, base64, waveform };
    } catch (err: any) {
      setStatus('Error');
      throw err;
    } finally {
      setIsBusy(false);
    }
  }, []);

  const renderMaster = async (media: any, layers: SoundLayer[], markers: Marker[], masterVol: number, sourceVol: number, includeMasterAudio: boolean = false) => {
    if (!media || isBusy) return;
    const anySolo = layers.some(l => l.isSolo) || markers.some(m => m.isSolo);
    setIsBusy(true);
    setStatus('Mixing Studio Master...');
    const mVol = (masterVol / 100);

    try {
      const inputs = ['-i', 'v.mp4'];
      await ffmpegService.writeFile('v.mp4', Uint8Array.from(atob(media.base64), c => c.charCodeAt(0)));
      let audioIdx = 1;
      const filters: string[] = [];
      const labels = [];

      filters.push(`[0:a]volume=${((sourceVol/100) * mVol).toFixed(3)},afade=t=out:st=7.8:d=0.2[a0]`);
      labels.push('[a0]');

      for (const l of layers) {
        if (l.audioBase64 && !(l.isMuted || (anySolo && !l.isSolo))) {
          const fn = `l_${l.id}.wav`;
          await ffmpegService.writeFile(fn, Uint8Array.from(atob(l.audioBase64), c => c.charCodeAt(0)));
          inputs.push('-i', fn);

          const trimS = l.trimStart || 0;
          const trimE = l.trimEnd || 8;
          const clipDur = trimE - trimS;
          const delay = Math.floor((l.time || 0) * 1000);

          const fadeInSec = Math.max(0.001, (l.fadeInMs || 0) / 1000);
          const fadeOutSec = Math.max(0.001, (l.fadeOutMs || 0) / 1000);
          const safeFadeIn = Math.min(clipDur / 2, fadeInSec);
          const safeFadeOut = Math.min(clipDur / 2, fadeOutSec);
          const fadeOutStart = Math.max(0, clipDur - safeFadeOut);

          const p = l.pan / 100, left = (1 - p).toFixed(2), right = (1 + p).toFixed(2);
          const vol = ((l.volume / 100) * mVol).toFixed(3);

          filters.push(`[${audioIdx}:a]atrim=start=${trimS.toFixed(4)}:end=${trimE.toFixed(4)},asetpts=PTS-STARTPTS,afade=t=in:st=0:d=${safeFadeIn.toFixed(4)}:curve=qsin,afade=t=out:st=${fadeOutStart.toFixed(4)}:d=${safeFadeOut.toFixed(4)}:curve=qsin,adelay=${delay}|${delay},volume=${vol},pan=stereo|c0<${left}*c0|c1<${right}*c1[al${audioIdx}]`);
          labels.push(`[al${audioIdx}]`); audioIdx++;
        }
      }

      for (const m of markers) {
        if (m.audioBase64 && !(m.isMuted || (anySolo && !m.isSolo))) {
          const fn = `m_${m.id}.wav`;
          await ffmpegService.writeFile(fn, Uint8Array.from(atob(m.audioBase64), c => c.charCodeAt(0)));
          inputs.push('-i', fn);

          const selectionDur = m.trimEnd - m.trimStart;
          const fadeInSec = Math.max(0.001, (m.fadeInMs || 0) / 1000);
          const fadeOutSec = Math.max(0.001, (m.fadeOutMs || 0) / 1000);

          const safeFadeIn = Math.min(selectionDur / 2, fadeInSec);
          const safeFadeOut = Math.min(selectionDur / 2, fadeOutSec);
          const fadeOutStart = Math.max(0, selectionDur - safeFadeOut);

          const p = m.pan / 100, left = (1 - p).toFixed(2), right = (1 + p).toFixed(2);
          const vol = ((m.volume / 100) * mVol).toFixed(3);
          const delay = Math.floor(m.time * 1000);

          filters.push(`[${audioIdx}:a]atrim=start=${m.trimStart.toFixed(4)}:end=${m.trimEnd.toFixed(4)},asetpts=PTS-STARTPTS,afade=t=in:st=0:d=${safeFadeIn.toFixed(4)}:curve=qsin,afade=t=out:st=${fadeOutStart.toFixed(4)}:d=${safeFadeOut.toFixed(4)}:curve=qsin,adelay=${delay}|${delay},volume=${vol},pan=stereo|c0<${left}*c0|c1<${right}*c1[am${audioIdx}]`);
          labels.push(`[am${audioIdx}]`); audioIdx++;
        }
      }

      const complex = `${filters.join(';')};${labels.join('')}amix=inputs=${labels.length}:duration=first:normalize=0,alimiter=limit=0.95:level=0[out]`;

      await ffmpegService.exec([...inputs, '-filter_complex', complex, '-map', '0:v', '-map', '[out]', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-y', 'out.mp4']);

      const timestamp = Date.now();
      const outMp4 = await ffmpegService.readFile('out.mp4') as Uint8Array;

      setStatus('Exporting Final Video...');

      await Flow.download({ 
        base64: await uint8ToBase64(outMp4), 
        mimeType: 'video/mp4', 
        filename: `MondoSonico_Final_${timestamp}.mp4` 
      });

      if (includeMasterAudio) {
        setStatus('Exporting Master File...');
        await ffmpegService.exec(['-i', 'out.mp4', '-vn', '-acodec', 'pcm_s16le', '-ar', '44100', '-ac', '2', '-y', 'out.wav']);
        const outWav = await ffmpegService.readFile('out.wav') as Uint8Array;

        await Flow.download({
          base64: await uint8ToBase64(outWav),
          mimeType: 'audio/wav',
          filename: `MondoSonico_Master_STUDIO_${timestamp}.wav`
        });
      }

      setStatus('Exported ✓');
    } catch (err) {
      console.error(err);
      setStatus('Error');
    } finally {
      setIsBusy(false);
      setTimeout(() => setStatus('Ready'), 2000);
    }
  };

  const exportStems = async (duration: number, layers: SoundLayer[], markers: Marker[]) => {
    setIsBusy(true);
    setStatus('Bundling Stems...');
    const zip = new JSZip();
    const usedFilenames = new Set<string>();
    const sanitize = (s: string, fallback: string) => (s || fallback).replace(/[^a-z0-9]/gi, '_').toLowerCase().slice(0, 15);

    const getUniqueFilename = (base: string) => {
      let finalName = base;
      let counter = 1;
      while (usedFilenames.has(finalName)) {
        finalName = base.replace(/\.wav$/, `_(${counter}).wav`);
        counter++;
      }
      usedFilenames.add(finalName);
      return finalName;
    };

    try {
      for (let i = 0; i < layers.length; i++) {
        const l = layers[i];
        if (!l.audioBase64) continue;

        setStatus(`Processing Ambient Stem ${i + 1}...`);
        const fn = `l_${l.id}.wav`;
        const outFn = `stem_ambient_${l.id}.wav`;
        await ffmpegService.writeFile(fn, Uint8Array.from(atob(l.audioBase64), c => c.charCodeAt(0)));

        const vol = (l.volume / 100).toFixed(3);
        const p = l.pan / 100, left = (1 - p).toFixed(2), right = (1 + p).toFixed(2);

        const clipStart = l.time || 0;
        const trimS = l.trimStart || 0;
        const trimE = l.trimEnd || 8;
        const clipDur = trimE - trimS;
        const delayMs = Math.floor(clipStart * 1000);

        const fadeInSec = Math.max(0.001, (l.fadeInMs || 0) / 1000);
        const fadeOutSec = Math.max(0.001, (l.fadeOutMs || 0) / 1000);
        const safeFadeIn = Math.min(clipDur / 2, fadeInSec);
        const safeFadeOut = Math.min(clipDur / 2, fadeOutSec);
        const fadeOutStart = Math.max(0, clipDur - safeFadeOut);

        await ffmpegService.exec([
          '-i', fn,
          '-filter_complex', `[0:a]atrim=start=${trimS.toFixed(4)}:end=${trimE.toFixed(4)},asetpts=PTS-STARTPTS,afade=t=in:st=0:d=${safeFadeIn.toFixed(4)},afade=t=out:st=${fadeOutStart.toFixed(4)}:d=${safeFadeOut.toFixed(4)},adelay=${delayMs}|${delayMs},apad=whole_len=${Math.floor(duration * 44100)},atrim=end=${duration},volume=${vol},pan=stereo|c0<${left}*c0|c1<${right}*c1[out]`,
          '-map', '[out]', '-y', outFn
        ]);

        const wav = await ffmpegService.readFile(outFn) as Uint8Array;
        const stemName = getUniqueFilename(`AMBIENT_${sanitize(l.prompt, `layer_${i+1}`)}.wav`);
        zip.file(stemName, wav);
      }

      for (let i = 0; i < markers.length; i++) {
        const m = markers[i];
        if (!m.audioBase64) continue;

        setStatus(`Processing ${m.type} Stem ${i + 1}...`);
        const fn = `m_${m.id}.wav`;
        const outFn = `stem_marker_${m.id}.wav`;
        await ffmpegService.writeFile(fn, Uint8Array.from(atob(m.audioBase64), c => c.charCodeAt(0)));

        const selectionDur = m.trimEnd - m.trimStart;
        const fadeInSec = Math.max(0.001, (m.fadeInMs || 0) / 1000);
        const fadeOutSec = Math.max(0.001, (m.fadeOutMs || 0) / 1000);
        const safeFadeIn = Math.min(selectionDur / 2, fadeInSec);
        const safeFadeOut = Math.min(selectionDur / 2, fadeOutSec);
        const fadeOutStart = Math.max(0, selectionDur - safeFadeOut);

        const vol = (m.volume / 100).toFixed(3);
        const p = m.pan / 100, left = (1 - p).toFixed(2), right = (1 + p).toFixed(2);
        const delay = Math.floor(m.time * 1000);

        await ffmpegService.exec([
          '-i', fn,
          '-filter_complex', `[0:a]atrim=start=${m.trimStart.toFixed(4)}:end=${m.trimEnd.toFixed(4)},asetpts=PTS-STARTPTS,afade=t=in:st=0:d=${safeFadeIn.toFixed(4)},afade=t=out:st=${fadeOutStart.toFixed(4)}:d=${safeFadeOut.toFixed(4)},adelay=${delay}|${delay},apad=whole_len=${Math.floor(duration * 44100)},atrim=end=${duration},volume=${vol},pan=stereo|c0<${left}*c0|c1<${right}*c1[out]`,
          '-map', '[out]', '-y', outFn
        ]);

        const wav = await ffmpegService.readFile(outFn) as Uint8Array;
        const stemName = getUniqueFilename(`${m.type.toUpperCase()}_${sanitize(m.prompt, `marker_${i+1}`)}.wav`);
        zip.file(stemName, wav);
      }

      setStatus('Compressing Archive...');
      const zipBlob = await zip.generateAsync({ type: 'blob' });
      const zipBase64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(zipBlob);
      });

      await Flow.download({
        base64: zipBase64,
        mimeType: 'application/zip',
        filename: `MondoSonico_Stems_${Date.now()}.zip`
      });

      setStatus('Stems Ready ✓');
    } catch (err) {
      console.error(err);
      setStatus('Error');
    } finally {
      setIsBusy(false);
      setTimeout(() => setStatus('Ready'), 2000);
    }
  };

  return { isBusy, status, setStatus, generateAudio, renderMaster, exportStems };
}

import React, { useRef } from 'react';

interface Props {
 start: number; end: number; duration: number;
 fadeInMs?: number; fadeOutMs?: number;
 waveform?: number[];
 onChange: (s: number, e: number) => void;
 onFadeChange?: (ins: number, out: number) => void;
 accentColor?: string;
 disabled?: boolean;
}

export const SourceTrimmer: React.FC<Props> = ({ 
  start, end, duration, fadeInMs = 0, fadeOutMs = 0, 
  waveform, onChange, onFadeChange, accentColor = '#FF6818', disabled 
}) => {
 const containerRef = useRef<HTMLDivElement>(null);

  const handleDrag = (e: React.MouseEvent, type: 'start' | 'end' | 'both') => {
   if (disabled || !containerRef.current) return;
   const rect = containerRef.current.getBoundingClientRect();
   const startX = e.clientX, iS = start, iE = end;

   const move = (ev: MouseEvent) => {
     const dt = ((ev.clientX - startX) / rect.width) * duration;
     if (type === 'start') {
       onChange(Math.max(0, Math.min(iE - 0.1, iS + dt)), end);
     } else if (type === 'end') {
       onChange(start, Math.max(iS + 0.1, Math.min(duration, iE + dt)));
     } else {
       const nS = Math.max(0, Math.min(duration - (iE - iS), iS + dt));
       onChange(nS, nS + (iE - iS));
     }
   };

   const up = () => {
     window.removeEventListener('mousemove', move);
     window.removeEventListener('mouseup', up);
   };

   window.addEventListener('mousemove', move);
   window.addEventListener('mouseup', up);
 };

  const handleDragFade = (e: React.MouseEvent, type: 'in' | 'out') => {
    if (disabled || !containerRef.current || !onFadeChange) return;
    e.stopPropagation();
    const selectionDur = Math.max(0.1, end - start);

    const move = (ev: MouseEvent) => {
      const rectNow = containerRef.current!.getBoundingClientRect();
      const relX = (ev.clientX - rectNow.left) / rectNow.width;
      const timeAtMouse = relX * duration;

      if (type === 'in') {
        const newFadeInSec = Math.max(0, Math.min(selectionDur, timeAtMouse - start));
        onFadeChange(Math.round(newFadeInSec * 1000), fadeOutMs);
      } else {
        const newFadeOutSec = Math.max(0, Math.min(selectionDur, end - timeAtMouse));
        onFadeChange(fadeInMs, Math.round(newFadeOutSec * 1000));
      }
    };

    const up = () => { 
      document.body.style.cursor = '';
      window.removeEventListener('mousemove', move); 
      window.removeEventListener('mouseup', up); 
    };

    document.body.style.cursor = 'ew-resize';
    window.addEventListener('mousemove', move); 
    window.addEventListener('mouseup', up);
  };

 const startPct = (start / duration) * 100;
 const endPct = (end / duration) * 100;
 const selectionDur = Math.max(0.1, end - start);
 const fadeInPct = ((fadeInMs / 1000) / selectionDur) * 100;
 const fadeOutPct = ((fadeOutMs / 1000) / selectionDur) * 100;

 return (
   <div ref={containerRef} className="relative w-full h-full cursor-crosshair select-none bg-[#F4F2EE]">
     {/* Waveform Estática (Representa el buffer completo de 8s) */}
     <div className="absolute inset-0 flex items-center justify-around pointer-events-none px-4">
       {waveform && waveform.length > 0 ? (
         <div className="w-full h-[60%] flex items-center gap-[1px]">
           {waveform.map((p, i) => {
             const posPct = (i / waveform.length) * 100;
             const isActive = posPct >= startPct && posPct <= endPct;
             return (
               <div
                 key={i}
                 className="flex-1 rounded-full"
                 style={{
                   height: `${Math.max(10, p * 100)}%`,
                   background: isActive ? accentColor : '#17171715'
                 }}
               />
             );
           })}
         </div>
       ) : (
         <div className="text-[8px] font-black opacity-10 tracking-[0.2em] uppercase">No Buffer Data</div>
       )}
     </div>

     {/* Overlays de zona inactiva */}
     <div className="absolute inset-y-0 left-0 bg-[#171717]/5" style={{ width: `${startPct}%` }} />
     <div className="absolute inset-y-0 right-0 bg-[#171717]/5" style={{ left: `${endPct}%` }} />

     {/* Ventana de Selección */}
     <div
       className="absolute top-0 bottom-0 border-x-2 cursor-grab active:cursor-grabbing"
       style={{
         left: `${startPct}%`,
         width: `${endPct - startPct}%`,
         borderColor: accentColor,
         background: `${accentColor}05`
       }}
       onMouseDown={e => handleDrag(e, 'both')}
     >
       <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible" preserveAspectRatio="none" viewBox="0 0 100 100">
          {fadeInMs > 0 && (
            <>
              <path d={`M 0,100 L ${fadeInPct},0 L ${fadeInPct},100 Z`} fill="white" opacity="0.1" />
              <line x1="0" y1="100" x2={fadeInPct} y2="0" stroke="white" strokeWidth="1" opacity="0.9" />
            </>
          )}
          {fadeOutMs > 0 && (
            <>
              <path d={`M ${100 - fadeOutPct},100 L ${100 - fadeOutPct},0 L 100,100 Z`} fill="white" opacity="0.1" />
              <line x1={100 - fadeOutPct} y1="0" x2="100" y2="100" stroke="white" strokeWidth="1" opacity="0.9" />
            </>
          )}
        </svg>
     </div>

     {/* Manejadores de Recorte */}
     <div
       className="absolute top-0 bottom-0 w-6 -translate-x-1/2 cursor-ew-resize flex items-center justify-center z-20 group"
       style={{ left: `${startPct}%` }}
       onMouseDown={e => handleDrag(e, 'start')}
     >
       <div className="w-1.5 h-[35%] rounded-full transition-transform group-hover:scale-y-125" style={{ backgroundColor: accentColor }} />
     </div>

     <div
       className="absolute top-0 bottom-0 w-6 -translate-x-1/2 cursor-ew-resize flex items-center justify-center z-20 group"
       style={{ left: `${endPct}%` }}
       onMouseDown={e => handleDrag(e, 'end')}
     >
       <div className="w-1.5 h-[35%] rounded-full transition-transform group-hover:scale-y-125" style={{ backgroundColor: accentColor }} />
     </div>

      {/* Nodos de Fade */}
      {!disabled && onFadeChange && (
        <>
          <div className="absolute top-0 w-8 h-8 -translate-x-1/2 cursor-ew-resize flex items-center justify-center z-40 group/f" style={{ left: `${startPct + (fadeInPct * (selectionDur/duration))}%` }} onMouseDown={e => handleDragFade(e, 'in')}>
            <div className="w-3 h-3 bg-white rounded-full border-[1.5px] border-[#151515] shadow-lg group-hover/f:scale-125 transition-transform" />
          </div>
          <div className="absolute top-0 w-8 h-8 -translate-x-1/2 cursor-ew-resize flex items-center justify-center z-40 group/f" style={{ left: `${endPct - (fadeOutPct * (selectionDur/duration))}%` }} onMouseDown={e => handleDragFade(e, 'out')}>
            <div className="w-3 h-3 bg-white rounded-full border-[1.5px] border-[#151515] shadow-lg group-hover/f:scale-125 transition-transform" />
          </div>
        </>
      )}
   </div>
 );
};

import React, { useState, useRef, useEffect } from 'react';
import { FocusArea } from '../types';

interface Props {
 area?: FocusArea;
 onChange: (area: FocusArea) => void;
 onClose: () => void;
}

export const AreaSelector: React.FC<Props> = ({ area, onChange, onClose }) => {
 const containerRef = useRef<HTMLDivElement>(null);
 const [isDragging, setIsDragging] = useState(false);
 const [startPos, setStartPos] = useState({ x: 0, y: 0 });

 const handleMouseDown = (e: React.MouseEvent) => {
   if (!containerRef.current) return;
   const rect = containerRef.current.getBoundingClientRect();
   const x = (e.clientX - rect.left) / rect.width;
   const y = (e.clientY - rect.top) / rect.height;
   setStartPos({ x, y });
   setIsDragging(true);
   onChange({ x, y, w: 0.01, h: 0.01 });
 };

 useEffect(() => {
   if (!isDragging) return;
   const move = (e: MouseEvent) => {
     if (!containerRef.current) return;
     const rect = containerRef.current.getBoundingClientRect();
     const curX = (e.clientX - rect.left) / rect.width;
     const curY = (e.clientY - rect.top) / rect.height;

     const x = Math.min(startPos.x, curX);
     const y = Math.min(startPos.y, curY);
     const w = Math.abs(curX - startPos.x);
     const h = Math.abs(curY - startPos.y);

     onChange({
       x: Math.max(0, Math.min(1, x)),
       y: Math.max(0, Math.min(1, y)),
       w: Math.max(0.01, Math.min(1 - x, w)),
       h: Math.max(0.01, Math.min(1 - y, h))
     });
   };
   const up = () => setIsDragging(false);
   window.addEventListener('mousemove', move);
   window.addEventListener('mouseup', up);
   return () => {
     window.removeEventListener('mousemove', move);
     window.removeEventListener('mouseup', up);
   };
 }, [isDragging, startPos, onChange]);

 return (
   <div
     ref={containerRef}
     className="absolute inset-0 z-40 bg-black/20 backdrop-blur-[2px] cursor-crosshair"
     onMouseDown={handleMouseDown}
   >
     <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-cyan-500 text-black px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl flex items-center gap-2 animate-pulse">
       <span className="material-symbols-outlined text-[14px]">open_in_full</span> Drag to define focus area
     </div>

     {area && (
       <div
         className="absolute border-2 border-cyan-400 bg-cyan-400/10 shadow-[0_0_20px_rgba(34,211,238,0.3)]"
         style={{
           left: `${area.x * 100}%`,
           top: `${area.y * 100}%`,
           width: `${area.w * 100}%`,
           height: `${area.h * 100}%`
         }}
       >
         <div className="absolute -top-6 left-0 text-[9px] font-bold text-cyan-400 bg-black/80 px-2 py-0.5 rounded uppercase tracking-tighter">
           Focus: {(area.w * 100).toFixed(0)}% x {(area.h * 100).toFixed(0)}%
         </div>
         {/* Corner accents */}
         <div className="absolute top-0 left-0 w-1.5 h-1.5 border-t border-l border-white" />
         <div className="absolute top-0 right-0 w-1.5 h-1.5 border-t border-r border-white" />
         <div className="absolute bottom-0 left-0 w-1.5 h-1.5 border-b border-l border-white" />
         <div className="absolute bottom-0 right-0 w-1.5 h-1.5 border-b border-r border-white" />
       </div>
     )}

     <button
       onClick={(e) => { e.stopPropagation(); onClose(); }}
       className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest shadow-2xl flex items-center gap-2 hover:scale-105 transition-transform"
     >
       <span className="material-symbols-outlined text-[16px]">check</span> Finish Selection
     </button>
   </div>
 );
};

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private buffers: Map<string, AudioBuffer> = new Map();
  private activeSources: Map<string, { source: AudioBufferSourceNode, gain: GainNode }> = new Map();
  private masterBus: GainNode | null = null;
  private analyser: AnalyserNode | null = null;
  private levelData: Uint8Array | null = null;

  constructor() {}

  private init() {
    if (this.ctx) return;
    this.ctx = new AudioContext();
    this.masterBus = this.ctx.createGain();
    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 256;
    this.levelData = new Uint8Array(this.analyser.frequencyBinCount);
    this.masterBus.connect(this.analyser);
    this.analyser.connect(this.ctx.destination);
  }

  getMasterLevel(): number {
    if (!this.analyser || !this.levelData) return 0;
    this.analyser.getByteTimeDomainData(this.levelData);
    let max = 0;
    for (let i = 0; i < this.levelData.length; i++) {
      const val = Math.abs(this.levelData[i] - 128) / 128;
      if (val > max) max = val;
    }
    return max;
  }

  isActive(id: string): boolean {
    return this.activeSources.has(id);
  }

  async loadBuffer(id: string, base64: string): Promise<void> {
    this.init();
    try {
      const binary = atob(base64);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const buffer = await this.ctx!.decodeAudioData(bytes.buffer);
      this.buffers.set(id, buffer);
    } catch (err) {
      console.error('Error decoding audio for', id, err);
    }
  }

  setMasterVolume(vol: number) {
    if (this.masterBus) {
      this.masterBus.gain.setTargetAtTime(vol / 100, this.ctx!.currentTime, 0.05);
    }
  }

  playMarker(id: string, options: {
    trimStart: number,
    trimEnd: number,
    fadeInMs: number,
    fadeOutMs: number,
    volume: number,
    pan: number,
    isMuted: boolean,
    offset?: number
  }) {
    this.init();
    if (options.isMuted) return;
    const buffer = this.buffers.get(id);
    if (!buffer) return;
    this.stop(id);
    const source = this.ctx!.createBufferSource();
    source.buffer = buffer;
    const gainNode = this.ctx!.createGain();
    const panner = this.ctx!.createStereoPanner();
    const baseDuration = options.trimEnd - options.trimStart;
    const offset = options.offset || 0;
    const remainingDuration = Math.max(0, baseDuration - offset);
    if (remainingDuration <= 0) return;
    const now = this.ctx!.currentTime;
    const vol = options.volume / 100;
    const fadeInSec = (options.fadeInMs || 0) / 1000;
    const fadeOutSec = (options.fadeOutMs || 0) / 1000;
    if (offset < fadeInSec && fadeInSec > 0) {
      const startVol = (offset / fadeInSec) * vol;
      gainNode.gain.setValueAtTime(startVol, now);
      gainNode.gain.linearRampToValueAtTime(vol, now + (fadeInSec - offset));
    } else {
      gainNode.gain.setValueAtTime(vol, now);
    }
    const fadeOutStartFromNow = Math.max(0, baseDuration - fadeOutSec - offset);
    if (fadeOutStartFromNow > 0) {
      gainNode.gain.setValueAtTime(vol, now + fadeOutStartFromNow);
      gainNode.gain.linearRampToValueAtTime(0, now + remainingDuration);
    } else {
      const progressInFadeOut = (offset - (baseDuration - fadeOutSec)) / fadeOutSec;
      const currentFadeOutVol = vol * Math.max(0, 1 - progressInFadeOut);
      gainNode.gain.setValueAtTime(currentFadeOutVol, now);
      gainNode.gain.linearRampToValueAtTime(0, now + remainingDuration);
    }
    panner.pan.setValueAtTime(options.pan / 100, now);
    source.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(this.masterBus!);
    source.start(now, options.trimStart + offset, remainingDuration);
    this.activeSources.set(id, { source, gain: gainNode });
    source.onended = () => { if (this.activeSources.get(id)?.source === source) this.activeSources.delete(id); };
  }

  playLayer(id: string, options: { 
    offset: number, 
    volume: number, 
    pan: number, 
    isMuted: boolean, 
    trimStart?: number, 
    trimEnd?: number,
    timelineDuration?: number,
    fadeInMs?: number,
    fadeOutMs?: number
  }) {
    this.init();
    if (options.isMuted) return;
    const buffer = this.buffers.get(id);
    if (!buffer) return;
    this.stop(id);
    const source = this.ctx!.createBufferSource();
    source.buffer = buffer;
    source.loop = true;

    const tS = options.trimStart || 0;
    const tE = options.trimEnd || 8;
    const loopDur = tE - tS;

    if (options.trimStart !== undefined && options.trimEnd !== undefined) {
      source.loopStart = tS;
      source.loopEnd = tE;
    }

    const gainNode = this.ctx!.createGain();
    const panner = this.ctx!.createStereoPanner();
    const now = this.ctx!.currentTime;

    // Fade Logic Integration for Ambiance
    const vol = options.volume / 100;
    const fadeInSec = (options.fadeInMs || 0) / 1000;
    const fadeOutSec = (options.fadeOutMs || 0) / 1000;
    const baseDuration = options.timelineDuration || loopDur;
    const offset = options.offset || 0;
    const remainingDuration = Math.max(0, baseDuration - offset);

    if (offset < fadeInSec && fadeInSec > 0) {
      const startVol = (offset / fadeInSec) * vol;
      gainNode.gain.setValueAtTime(startVol, now);
      gainNode.gain.linearRampToValueAtTime(vol, now + (fadeInSec - offset));
    } else {
      gainNode.gain.setValueAtTime(vol, now);
    }

    const fadeOutStartFromNow = Math.max(0, baseDuration - fadeOutSec - offset);
    if (fadeOutStartFromNow > 0) {
      gainNode.gain.setValueAtTime(vol, now + fadeOutStartFromNow);
      gainNode.gain.linearRampToValueAtTime(0, now + remainingDuration);
    } else {
      const progressInFadeOut = (offset - (baseDuration - fadeOutSec)) / fadeOutSec;
      const currentFadeOutVol = vol * Math.max(0, 1 - progressInFadeOut);
      gainNode.gain.setValueAtTime(currentFadeOutVol, now);
      gainNode.gain.linearRampToValueAtTime(0, now + remainingDuration);
    }

    panner.pan.setValueAtTime(options.pan / 100, now);
    source.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(this.masterBus!);

    const bufferOffset = tS + (options.offset % loopDur);
    source.start(now, bufferOffset);

    if (options.timelineDuration !== undefined) {
      const remaining = options.timelineDuration - options.offset;
      if (remaining > 0) {
        source.stop(now + remaining);
      }
    }

    this.activeSources.set(id, { source, gain: gainNode });
  }

  stop(id: string) {
    const active = this.activeSources.get(id);
    if (active) {
      try { active.source.stop(); } catch (e) {}
      this.activeSources.delete(id);
    }
  }

  stopAll() { this.activeSources.forEach((v, k) => this.stop(k)); }
  resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }
}

export const audioEngine = new AudioEngine();

import React, { useRef, useState } from 'react';
import { Flow } from 'flow-sdk';
import { SoundLayer, Marker } from '../types';
import { audioEngine } from '../services/audioEngine';
import { ProjectIcon } from './CustomIcons';

interface Props {
  data: {
    media: any | null;
    ambientLayers: SoundLayer[];
    markers: Marker[];
    masterVolume: number;
    sourceVolume: number;
    genMode: 'fast' | 'high';
  };
  onLoad: (data: any) => void;
}

export const SessionManager: React.FC<Props> = ({ data, onLoad }) => {
  const [isOpen, setIsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isMediaLoaded = !!data.media;

  const handleSave = async () => {
    if (!isMediaLoaded) return;
    const sessionData = JSON.stringify(data);
    const base64 = btoa(unescape(encodeURIComponent(sessionData)));

    await Flow.download({
      base64,
      mimeType: 'application/json',
      filename: `MondoSonico_Session_${new Date().toISOString().slice(0,10)}.json`
    });
    setIsOpen(false);
  };

  const handleLoadClick = () => {
    fileInputRef.current?.click();
    setIsOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        const parsed = JSON.parse(content);

        // Reload audio buffers into engine
        if (parsed.ambientLayers) {
          for (const layer of parsed.ambientLayers) {
            if (layer.audioBase64) await audioEngine.loadBuffer(layer.id, layer.audioBase64);
          }
        }
        if (parsed.markers) {
          for (const marker of parsed.markers) {
            if (marker.audioBase64) await audioEngine.loadBuffer(marker.id, marker.audioBase64);
          }
        }

        onLoad(parsed);
      } catch (err) {
        console.error("Error loading session", err);
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset
  };

  return (
    <div className="relative w-full">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`group flex items-center justify-center w-full h-[44px] rounded-full tracking-[0.5px] transition-all duration-200 cursor-pointer active:scale-[0.97] select-none ${isOpen ? 'bg-[#171717] text-white shadow-lg scale-[1.02]' : 'bg-[#d0cabf] text-[#1A1A1A] shadow-sm hover:bg-[#c0b9ad]'}`}
      >
        <span className="mr-2 flex items-center justify-center scale-90 text-inherit">
          <ProjectIcon />
        </span>
        <span className="whitespace-nowrap uppercase tracking-wider text-[13px] font-medium">Project</span>
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute top-[calc(100%+8px)] right-0 w-48 bg-[#fbfaf7] border-[1.5px] border-[#171717] rounded-2xl shadow-2xl z-50 overflow-hidden animate-dropdown origin-top-right">
            <button 
              onClick={handleSave}
              disabled={!isMediaLoaded}
              className={`w-full flex items-center gap-3 px-4 py-3 text-[11px] font-medium uppercase tracking-widest transition-all border-b border-[#17171710] ${isMediaLoaded ? 'text-[#171717] hover:bg-[#171717] hover:text-white cursor-pointer' : 'text-[#17171740] cursor-not-allowed'}`}
            >
              <span className="material-symbols-outlined text-[18px]">save</span>
              Save Project
            </button>
            <button 
              onClick={handleLoadClick}
              className="w-full flex items-center gap-3 px-4 py-3 text-[11px] font-medium uppercase tracking-widest text-[#171717] hover:bg-[#171717] hover:text-white transition-all cursor-pointer"
            >
              <span className="material-symbols-outlined text-[18px]">folder_open</span>
              Open Project
            </button>
          </div>
        </>
      )}

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept=".json" 
        className="hidden" 
      />
    </div>
  );
};

