import React, { useRef } from 'react';
import { Marker, SoundLayer } from '../types';

interface Props {
  item: Marker | SoundLayer;
  duration: number;
  pixelsPerSecond: number;
  anySoloActive: boolean;
  onUpdate: (up: Partial<Marker | SoundLayer>) => void;
  accentColor: string;
}

export const AudioClip: React.FC<Props> = ({ item, duration, pixelsPerSecond, anySoloActive, onUpdate, accentColor }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const startTime = item.time ?? 0;
  const trimStart = item.trimStart ?? 0;
  const trimEnd = item.trimEnd ?? 8;
  const clipDuration = Math.max(0.1, trimEnd - trimStart);
  const fadeInMs = item.fadeInMs ?? 0;
  const fadeOutMs = item.fadeOutMs ?? 0;

  const isDim = item.isMuted || (anySoloActive && !item.isSolo);

  const handleDragPosition = (e: React.MouseEvent) => {
    e.stopPropagation();
    const startX = e.clientX;
    const initialTime = item.time ?? 0;

    const move = (ev: MouseEvent) => {
      const deltaT = (ev.clientX - startX) / pixelsPerSecond;
      onUpdate({ time: Math.max(0, Math.min(duration - clipDuration, initialTime + deltaT)) } as any);
    };

    const up = () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
    };

    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
  };

  const handleTrim = (e: React.MouseEvent, type: 'start' | 'end') => {
    e.stopPropagation();
    const startX = e.clientX;
    const iS = trimStart;
    const iE = trimEnd;
    const iTime = item.time ?? 0;

    const move = (ev: MouseEvent) => {
      const deltaT = (ev.clientX - startX) / pixelsPerSecond;
      if (type === 'start') {
        const nS = Math.max(0, Math.min(iE - 0.1, iS + deltaT));
        const actualDelta = nS - iS;
        // Mover el tiempo de inicio sincronizadamente con el trimStart 
        // para que la forma de onda parezca quedarse quieta en el espacio global.
        onUpdate({ trimStart: nS, time: Math.max(0, iTime + actualDelta) } as any);
      } else {
        onUpdate({ trimEnd: Math.max(iS + 0.1, Math.min(8, iE + deltaT)) });
      }
    };

    const up = () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
    };

    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
  };

  const handleFade = (e: React.MouseEvent, type: 'in' | 'out') => {
    e.stopPropagation();
    const startX = e.clientX;
    const iFade = type === 'in' ? fadeInMs : fadeOutMs;

    const move = (ev: MouseEvent) => {
      const deltaMs = ((ev.clientX - startX) / pixelsPerSecond) * 1000;
      const newVal = Math.max(0, Math.min(clipDuration * 1000, iFade + (type === 'in' ? deltaMs : -deltaMs)));
      if (type === 'in') onUpdate({ fadeInMs: newVal } as any);
      else onUpdate({ fadeOutMs: newVal } as any);
    };

    const up = () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
    };

    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', up);
  };

  // Cálculos de Viewport Absolutos
  const leftPx = startTime * pixelsPerSecond;
  const widthPx = clipDuration * pixelsPerSecond;

  // La forma de onda siempre representa 8 segundos de buffer. 
  // La escalamos a píxeles fijos para que sea independiente del tamaño del clip.
  const bufferWidthPx = 8 * pixelsPerSecond;
  const bufferOffsetPx = -(trimStart * pixelsPerSecond);

  // Fades relativos al contenedor del clip
  const fadeInPct = ((fadeInMs / 1000) / clipDuration) * 100;
  const fadeOutPct = ((fadeOutMs / 1000) / clipDuration) * 100;

  return (
    <div
      ref={containerRef}
      className={`absolute top-1 bottom-1 rounded-md border-[1.5px] overflow-hidden group cursor-grab active:cursor-grabbing hover:shadow-md ${isDim ? 'opacity-30 grayscale-[0.8]' : 'opacity-100'}`}
      style={{ 
        left: `${leftPx}px`, 
        width: `${widthPx}px`, 
        backgroundColor: `${accentColor}20`, 
        borderColor: accentColor 
      }}
      onMouseDown={handleDragPosition}
    >
      {/* Waveform anclada a píxeles fijos: No se estira al recortar */}
      <div 
        className="absolute top-0 bottom-0 flex items-center gap-[1px] pointer-events-none opacity-40"
        style={{ 
          left: `${bufferOffsetPx}px`, 
          width: `${bufferWidthPx}px` 
        }}
      >
        {item.waveform?.map((h, i) => (
          <div key={i} className="flex-1 bg-current" style={{ height: `${Math.max(0.1, h * 100)}%`, color: accentColor }} />
        ))}
      </div>

      {/* Envelopes (Fades) */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none" preserveAspectRatio="none">
        <path d={`M 0,100 L ${fadeInPct}%,0 L ${fadeInPct}%,100 Z`} fill={accentColor} opacity="0.1" />
        <path d={`M ${100 - fadeOutPct}%,100 L ${100 - fadeOutPct}%,0 L 100,100 Z`} fill={accentColor} opacity="0.1" />
      </svg>

      {/* Fade Handles */}
      <div 
        className="absolute top-0 w-3 h-3 bg-white border border-[#171717] rounded-full cursor-ew-resize z-20 opacity-0 group-hover:opacity-100 transition-opacity"
        style={{ left: `${fadeInPct}%`, transform: 'translateX(-50%)' }}
        onMouseDown={e => handleFade(e, 'in')}
      />
      <div 
        className="absolute top-0 w-3 h-3 bg-white border border-[#171717] rounded-full cursor-ew-resize z-20 opacity-0 group-hover:opacity-100 transition-opacity"
        style={{ left: `${100 - fadeOutPct}%`, transform: 'translateX(-50%)' }}
        onMouseDown={e => handleFade(e, 'out')}
      />

      {/* Trim Handles */}
      <div 
        className="absolute inset-y-0 left-0 w-2 cursor-ew-resize hover:bg-black/10 z-10"
        onMouseDown={e => handleTrim(e, 'start')}
      />
      <div 
        className="absolute inset-y-0 right-0 w-2 cursor-ew-resize hover:bg-black/10 z-10"
        onMouseDown={e => handleTrim(e, 'end')}
      />

      <div className="absolute bottom-0.5 left-1 text-[8px] font-bold uppercase tracking-tighter pointer-events-none truncate pr-2" style={{ color: accentColor }}>
        {item.prompt || (item.type === 'Ambience' ? 'Ambience' : (item as Marker).type)}
      </div>
    </div>
  );
};

import React from 'react';
import { MondoLogo, MediaIcon, StemIcon } from './CustomIcons';

