import React, { useEffect } from 'react';

export type ToastType = 'Ambiance' | 'Foley' | 'SFX' | 'Success' | 'Error';

export interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

const TOAST_STYLES: Record<ToastType, { bg: string, text: string }> = {
  'Ambiance': { bg: '#009d50', text: 'white' },
  'Foley': { bg: '#ed7235', text: 'white' },
  'SFX': { bg: '#a696f8', text: 'white' },
  'Success': { bg: '#171717', text: 'white' },
  'Error': { bg: '#ff3b30', text: 'white' }
};

export const Toast: React.FC<{ toast: ToastMessage; onRemove: (id: string) => void }> = ({ toast, onRemove }) => {
  useEffect(() => {
    const timer = setTimeout(() => onRemove(toast.id), 3000);
    return () => clearTimeout(timer);
  }, [toast.id, onRemove]);

  const style = TOAST_STYLES[toast.type];

  return (
    <div 
      className="flex items-center gap-3 px-6 py-3 rounded-full shadow-2xl animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto"
      style={{ backgroundColor: style.bg, color: style.text }}
    >
      <span className="text-[12px] font-black uppercase tracking-widest">{toast.message}</span>
      <button 
        onClick={() => onRemove(toast.id)}
        className="ml-2 opacity-40 hover:opacity-100 transition-opacity cursor-pointer"
      >
        <span className="material-symbols-outlined text-[16px]">close</span>
      </button>
    </div>
  );
};

export const ToastContainer: React.FC<{ toasts: ToastMessage[]; onRemove: (id: string) => void }> = ({ toasts, onRemove }) => {
  return (
    <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[200] flex flex-col gap-3 items-center pointer-events-none w-full max-w-md">
      {toasts.map(t => (
        <Toast key={t.id} toast={t} onRemove={onRemove} />
      ))}
    </div>
  );
};
